#Centers the popup windows
def center_window(root, widthpopup, heightpopup):
    screen_width = root.winfo_screenwidth()
    screen_height = root.winfo_screenheight()
    x = (screen_width // 2) - (widthpopup // 2)
    y = (screen_height // 2) - (heightpopup // 2)
    root.geometry(f'{widthpopup}x{heightpopup}+{x}+{y}')
#Controls the Dropdown Menus
def on_select(event, dropdown_id, current_dropdown):
    selected = current_dropdown.get()
    if selected == "":
        for _, dd in dropdowns:
            dd.config(state="readonly")
    else:
        for _, dd in dropdowns:
            if dd != current_dropdown:
                dd.config(state="disabled")
#Controls what happens when main window is closed
def on_closing(root):
    root.destroy()
    root.quit()
#Controls the Proceed Button
def proceedButton():
    for label_text, dropdown in dropdowns:
        value = dropdown.get()
        if value != "":
            result = f"{label_text}_{value}"
            spherIndentEngine(result)
            root.quit()
            root.destroy()
            break
#Controls the About the Software button/window
def displayAboutInfo():
    # Define the links
    def open_linkPaper(event):
        webbrowser.open_new("https://example.com")
    def open_linkData(event):
        webbrowser.open_new("https://doi.org/10.18434/Mds2-4051")        
    def open_linkRepository(event):
        webbrowser.open_new("https://github.com/usnistgov/SpherIndent")                
    # Define the About Window
    about_window = tk.Toplevel()
    about_window.title("About SpherIndent")
    center_window(about_window, 440, 580)  # Matches width and height of the help window
    about_window.configure(bg="white")
    about_window.resizable(False, False)  
    # Clean UI Frame for container buffer
    main_frame = tk.Frame(about_window, bg="white")
    main_frame.pack(fill="both", expand=True, padx=20, pady=(15, 5))
    # Define Text Widgets
    text_widget = tk.Text(
        main_frame, 
        wrap="word", 
        bg="white", 
        font=("Arial", 10), 
        borderwidth=0, 
        highlightthickness=0
    )
    # Text
    text_widget.insert("1.0", "About SpherIndent\n", ("title", "center"))
    text_widget.insert("3.0", "The present version of SpherIndent was developed at the Material Measurement Laboratory (MML) in the National Institute of Standards and Technology (NIST), Gaithersburg, MD.\n", "body")
    text_widget.insert("5.0", "It was developed by Nicolas A. Alderete and Yvonne B. Gerbing during 2025-2026.\n", "body") 
    text_widget.insert("7.0", "This work was performed with funding from the CHIPS Metrology Program, part of CHIPS for America, National Institute of Standards and Technology, U.S. Department of Commerce.\n", "body")        
    text_widget.insert("9.0", "How to cite\n", ("heading", "center"))  
    text_widget.insert("11.0", "We appreciate recognition of our work by citing the following (click on the links):\n", "body_compact")  
    text_widget.insert("12.0", "Associated Peer Reviewed Publications\n", "linkPaper")
    text_widget.insert("13.0", "Associated Data Publications\n", "linkData")
    text_widget.insert("14.0", "Permanent Repository (for most updated version)\n", "linkRepository")
    text_widget.insert("17.0", "Contact Information\n", ("heading", "center")) 
    text_widget.insert("19.0", "For comments or suggestions write to: nicolas.alderete@nist.gov | yvonne.gerbig@nist.gov", "body")
    text_widget.tag_configure("center", justify="center")
    # Text Hierarchies
    text_widget.tag_configure("title", font=("Arial", 13, "bold"), foreground="#000000", spacing3=15)
    text_widget.tag_configure("heading", font=("Arial", 12, "bold"), foreground="#000000", spacing1=15, spacing3=8)
    text_widget.tag_configure("body", font=("Arial", 10), foreground="#000000", spacing2=4, spacing3=12)
    text_widget.tag_configure("body_compact", font=("Arial", 10), foreground="#000000", spacing2=4, spacing3=6)
    # Interactive Links
    text_widget.tag_configure("linkPaper", font=("Arial", 10, "bold"), foreground="#2980B9", underline=True, spacing3=6)
    text_widget.tag_configure("linkData", font=("Arial", 10, "bold"), foreground="#2980B9", underline=True, spacing3=6)
    text_widget.tag_configure("linkRepository", font=("Arial", 10, "bold"), foreground="#2980B9", underline=True, spacing3=12)
    # Cursor changes on hover
    text_widget.tag_bind("linkPaper", "<Enter>", lambda e: text_widget.config(cursor="hand2"))
    text_widget.tag_bind("linkPaper", "<Leave>", lambda e: text_widget.config(cursor=""))
    text_widget.tag_bind("linkData", "<Enter>", lambda e: text_widget.config(cursor="hand2"))
    text_widget.tag_bind("linkData", "<Leave>", lambda e: text_widget.config(cursor=""))
    text_widget.tag_bind("linkRepository", "<Enter>", lambda e: text_widget.config(cursor="hand2"))
    text_widget.tag_bind("linkRepository", "<Leave>", lambda e: text_widget.config(cursor=""))
    # Bindings
    text_widget.tag_bind("linkPaper", "<Button-1>", open_linkPaper)
    text_widget.tag_bind("linkData", "<Button-1>", open_linkData)
    text_widget.tag_bind("linkRepository", "<Button-1>", open_linkRepository)
    text_widget.pack(fill="both", expand=True)
    text_widget.config(state="disabled")
    #Close button
    close_btn = tk.Button(about_window, text="Close", font=("Arial", 10, "bold"), command=about_window.destroy)
    close_btn.pack(pady=10)  
