def retrieveRefProperties(materialNamelookup):
    if materialNamelookup.lower() in ('sapphire','al2o3','sapph'):
        MaterialPropertiesI = [403, 0.24]
    elif materialNamelookup.lower() in ('diamond','diamnd'):
        MaterialPropertiesI = [1141, 0.07]
    elif materialNamelookup.lower() in ('fusedsilica','fs','glass','silica','sio2'):
        MaterialPropertiesI = [72, 0.17]
    elif materialNamelookup.lower() in ('silicon','si'):
        MaterialPropertiesI = [165, 0.27]	   
    elif materialNamelookup.lower() in ('copper','cu'):
        MaterialPropertiesI = [120, 0.27]        
    else:
        MaterialPropertiesI = [0, 0.30]	   
    return MaterialPropertiesI
