#PopInSelectionPlotter############################################################################################################################################################################  
def PopInSelectionPlotter(popDetFlagFD, fdcurve, fdpins, fdcurveAll, instr, fontfeatures):
    if fdpins is not None and len(fdpins) > 0:
        current_pins = [list(p) for p in fdpins]
    else:
        current_pins = []       
    skip_test = False     
    fig, ax = plt.subplots(figsize=(10, 7))
    plt.subplots_adjust(bottom=0.2) 
    # Positioned at [left, bottom, width, height]
    ax_inset = fig.add_axes([0.15, 0.70, 0.15, 0.15])
    ax_inset.plot(fdcurveAll[:, 0], fdcurveAll[:, 1], '-k', linewidth=1, alpha=0.7) 
    ax_inset.set_xticks([]) 
    ax_inset.set_yticks([])
    def update_plot():
        current_xlim = ax.get_xlim() if ax.lines else None
        current_ylim = ax.get_ylim() if ax.lines else None
        ax.cla()
        ax.plot(fdcurve[:, 0], fdcurve[:, 1], '-r', marker='.', label='Loading Segment', markersize=2)
        
        if len(current_pins) > 0:
            for i, pin in enumerate(current_pins):
                label = 'Suggested PopIns' if i == 0 else "_nolegend_"
                ax.axvline(x=pin[0], color=(0, 0, 0, 0.5), linestyle='dashed', linewidth=1, label=label)
                ax.plot(pin[0], pin[1], 'xk', markersize=5)    
        ax.set_title('NanoIndentation Curve', fontsize=fontfeatures['TitleFontSize'])
        ax.set_xlabel('Indentation Depth (nm)', fontsize=fontfeatures['xylabelFontSize'])
        ylabel = 'Force (mN)' if instr == 'IIT' else 'Force (nN)'
        ax.set_ylabel(ylabel, fontsize=fontfeatures['xylabelFontSize'])
        ax.legend(loc="lower right", fontsize=fontfeatures['legendFontSize'])
        # Restore zoom limits if they existed
        if current_xlim and current_ylim:
            ax.set_xlim(current_xlim)
            ax.set_ylim(current_ylim)
        fig.canvas.draw_idle()
    def on_clear(event):
        current_pins.clear() 
        update_plot()
    def on_proceed(event):
        plt.close(fig) 
    def on_next_test(event):
        nonlocal skip_test
        skip_test = True
        plt.close(fig) 
    def on_click(event):
        if event.inaxes != ax: return
        if event.button == 2:
            on_proceed(None)
        elif event.button == 3 and len(current_pins) > 0:
            click_x = event.xdata
            distances = [abs(p[0] - click_x) for p in current_pins]
            if min(distances) < (ax.get_xlim()[1] * 0.05):
                current_pins.pop(distances.index(min(distances)))
        elif event.button == 1: 
            idx = (np.abs(fdcurve[:, 0] - event.xdata)).argmin()
            current_pins.append([fdcurve[idx, 0], fdcurve[idx, 1]])
        update_plot()
    def handle_close(event):
        fig.canvas.stop_event_loop()
    # Button Setup
    ax_clear = plt.axes([0.25, 0.05, 0.12, 0.043])
    ax_proc = plt.axes([0.41, 0.05, 0.14, 0.043])
    ax_next = plt.axes([0.57, 0.05, 0.12, 0.043])
    btn_clear = Button(ax_clear, 'Clear All', color='#f0f0f0', hovercolor='#e0e0e0')
    btn_proc = Button(ax_proc, 'Accept & Proceed', color='#f0f0f0', hovercolor='#e0e0e0')
    btn_next = Button(ax_next, 'Skip Test', color='#f0f0f0', hovercolor='#e0e0e0')
    for btn in [btn_clear, btn_proc, btn_next]:
        btn.label.set_fontname('Arial') 
        btn.label.set_fontsize(11)
        btn.label.set_color('black')
        btn.label.set_fontweight('bold')
        btn.ax.spines['top'].set_color('#a0a0a0')
        btn.ax.spines['bottom'].set_color('#a0a0a0')
        btn.ax.spines['left'].set_color('#a0a0a0')
        btn.ax.spines['right'].set_color('#a0a0a0')
    fig._buttons = [btn_clear, btn_proc, btn_next]
    btn_clear.on_clicked(on_clear)
    btn_proc.on_clicked(on_proceed)
    btn_next.on_clicked(on_next_test)
    fig.canvas.mpl_connect('button_press_event', on_click)
    fig.canvas.mpl_connect('close_event', handle_close)
    # Initial plot generation
    update_plot()
    manager = fig.canvas.manager
    if hasattr(manager, 'window'):
        backend_window = manager.window
        backend_window.withdraw()
        center_window(backend_window, int(fig.bbox.width), int(fig.bbox.height))
        backend_window.deiconify()
        backend_window.attributes('-topmost', True)
        backend_window.attributes('-topmost', False)
        backend_window.focus_force()
    plt.show(block=False) 
    fig.canvas.start_event_loop() 
    if not current_pins or len(current_pins) == 0:
        return np.array([]).reshape(0, 2), skip_test 
    final_arr = np.array(current_pins)
    final_arr = final_arr[final_arr[:, 0].argsort()]
    final_arr = np.unique(final_arr, axis=0)
    return final_arr, skip_test
#LoadingUnloadingCurveOverlapCalc#################################################################################################################################################################
def loadingUnloadingOverlap(fdloading, fdunloading):
    x1=fdloading[:,0];y1=fdloading[:,1]
    x2=fdunloading[:,0];y2=fdunloading[:,1]    
    # Find common x-range
    xMin = max(x1.min(), x2.min())
    xMax = min(x1.max(), x2.max())
    xCommon = np.linspace(xMin, xMax, 500)
    # Interpolate to a common x-grid
    f1 = interp1d(x1, y1, kind='linear', fill_value=(y1[0], y1[-1]), bounds_error=False)
    f2 = interp1d(x2, y2, kind='linear', fill_value=(y2[0], y2[-1]), bounds_error=False)
    y1Common = f1(xCommon)
    y2Common = f2(xCommon)
    # Compute the minimum and maximum y-values
    yMin = np.minimum(y1Common, y2Common)
    yMax = np.maximum(y1Common, y2Common)
    # Calculate the total area under the curves
    area1 = np.trapz(y1Common, xCommon)
    area2 = np.trapz(y2Common, xCommon)
    # Calculate the overlap coefficient
    overlap_coefficient=area2/area1
    if overlap_coefficient>=0.85:
        elastplastind=0
    else:
        elastplastind=1
    return elastplastind
#FDCurveSegmentPlottersSingleStep#################################################################################################################################################################
def fdSegmentPlotters(tdfarray, loadEndloc, holdEndloc, unloadEndloc, slopeDrift, ordinateDrift, idxDriftStart, goodnessDriftFit, 
                      driftcorrdisp, dfcorr, loadEndCorrloc, holdEndCorrloc, unloadEndCorrloc, savefigdir, testnum, sampName, fontfeatures):
    fig = plt.figure(figsize=(12, 6.))
    gs = GridSpec(3, 2, figure=fig)
    fig.suptitle('Test ' + str(testnum))
    ax1 = fig.add_subplot(gs[:, 0])
    ax2 = fig.add_subplot(gs[0, 1])
    ax3 = fig.add_subplot(gs[1, 1])
    ax4 = fig.add_subplot(gs[2, 1])           
    ax1.plot(tdfarray[:,1],tdfarray[:,2],'k', label='Raw Data')
    ax1.plot(tdfarray[loadEndloc,1],tdfarray[loadEndloc,2],'.r',markersize=8)
    ax1.plot(tdfarray[loadEndCorrloc,1],tdfarray[loadEndCorrloc,2],'xr',markersize=8)
    ax1.plot(tdfarray[holdEndloc,1],tdfarray[holdEndloc,2],'.r',markersize=8)
    ax1.plot(tdfarray[unloadEndloc,1],tdfarray[unloadEndloc,2],'.r', label='Segment Points', markersize=8)
    if not np.isnan(slopeDrift):
        ax1.plot(driftcorrdisp, tdfarray[:,2],'--k', label='Drift Corrected Data')
    ax1.plot(dfcorr[:,0], dfcorr[:,1],'--r', label='ZP & Mach. Comp. Corrected Data')
    ax1.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax1.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax1.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    ax1.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    ax2.plot(tdfarray[:,1],tdfarray[:,2],'k', label='Raw Data')
    ax2.plot(tdfarray[loadEndloc,1],tdfarray[loadEndloc,2],'.r',markersize=8)
    ax2.plot(tdfarray[holdEndloc,1],tdfarray[holdEndloc,2],'.r',markersize=8)
    ax2.plot(tdfarray[unloadEndloc,1],tdfarray[unloadEndloc,2],'.r', label='Segment Points', markersize=8)
    if not np.isnan(slopeDrift):
        ax2.plot(driftcorrdisp, tdfarray[:,2],'--k', label='Drift Corrected Data')
    ax2.plot(dfcorr[:,0], dfcorr[:,1],'--r', label='ZP & Mach. Comp. Corrected Data')
    ax2.set_xlim([tdfarray[loadEndloc-int(0.15*loadEndloc),1],1.05*tdfarray[loadEndloc,1]])
    ax2.set_ylim([tdfarray[loadEndloc-int(0.15*loadEndloc),2],1.05*tdfarray[loadEndloc,2]])            
    ax2.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax2.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax2.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    ax2.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])    
    ax3.plot(tdfarray[:,1],tdfarray[:,2],'k', label='Raw Data')
    ax3.plot(tdfarray[loadEndloc,1],tdfarray[loadEndloc,2],'.r',markersize=8)
    ax3.plot(tdfarray[holdEndloc,1],tdfarray[holdEndloc,2],'.r',markersize=8)
    ax3.plot(tdfarray[unloadEndloc,1],tdfarray[unloadEndloc,2],'.r', label='Segment Points', markersize=8)
    if not np.isnan(slopeDrift):
        ax3.plot(driftcorrdisp, tdfarray[:,2],'--k', label='Drift Corrected Data')
    ax3.plot(dfcorr[:,0], dfcorr[:,1],'--r', label='ZP & Mach. Comp. Corrected Data')
    ax3.set_xlim([0.85*tdfarray[-1,1],1.2*tdfarray[unloadEndloc,1]])
    ax3.set_ylim([0.85*tdfarray[-1,2],1.2*tdfarray[unloadEndloc,2]])            
    ax3.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax3.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax3.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])    
    ax3.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    if not np.isnan(slopeDrift):             
        ax4.plot(tdfarray[unloadEndloc:,0],tdfarray[unloadEndloc:,1],'ok', label='Thermal Drift Data')
        ax4.plot(tdfarray[unloadEndloc+idxDriftStart,0],tdfarray[idxDriftStart+unloadEndloc,1],'.r', label='Segment Points', markersize=8)
        ax4.plot(tdfarray[unloadEndloc+idxDriftStart:,0],slopeDrift*tdfarray[unloadEndloc+idxDriftStart:,0]+ordinateDrift, 
                label='Thermal Drift Data Fit(D='+str(round(slopeDrift,5))+'nm/s |'+r'$R^{2}$'+'='+str(round(goodnessDriftFit,3))+')')         
        ax4.set_xlabel('Time (s)', fontsize=fontfeatures['xylabelFontSize'])
        ax4.set_ylabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
        ax4.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
        ax4.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    else:
        ax4.plot(0.,0. ,'ok', label='No Thermal Drift Data')   
        ax4.set_xlabel('Time (s)', fontsize=fontfeatures['xylabelFontSize'])
        ax4.set_ylabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
        ax4.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
        ax4.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])        
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'Plt_PhData-Corrs_Test_'+str(testnum+1)+sampName), dpi=300, bbox_inches='tight')  
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'Plt_PhData-Corrs_Test_'+str(testnum+1)+sampName+'.svg'), format = 'svg')       
    axss = [ax1, ax2, ax3, ax4]
    return  axss
#AFM Detrender and ZeroPoint Plotter#################################################################################################################################################################
def DetrenderZeroPointPlotter(AppRetData, AppRetData_Detrended, locMinAppRet, PointsBeforeAfterMin, ZeroPointIndex, pwlfit, afmUsed, sampName, fontfeatures, directory, filenum):        
    fig = plt.figure(figsize=(6, 8))
    gs = GridSpec(3, 2, figure=fig)    
    ax1 = fig.add_subplot(gs[0, :])
    ax2 = fig.add_subplot(gs[1, :])
    ax3 = fig.add_subplot(gs[2, 0])
    ax4 = fig.add_subplot(gs[2, 1])
    
    ax1.plot(AppRetData[:,0], AppRetData[:,1], label='Raw')
    ax1.plot(AppRetData_Detrended[:,0], AppRetData_Detrended[:,1], label='Detrended')
    ax1.plot(AppRetData[0:locMinAppRet[0]-PointsBeforeAfterMin,0], AppRetData[0:locMinAppRet[0]-PointsBeforeAfterMin,1], label='Data for Detrend')
    ax1.set_title('Approach Curve', fontsize=fontfeatures['TitleFontSize'])
    ax1.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    ax1.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])

    ax2.plot(AppRetData[:,0], AppRetData[:,1], label='Raw')
    ax2.plot(AppRetData[0:locMinAppRet[0]-PointsBeforeAfterMin,0], AppRetData[0:locMinAppRet[0]-PointsBeforeAfterMin,1], label='Data for Detrend')    
    ax2.set_ylim([(1-0.1*np.sign(np.min(AppRetData[:,1])))*np.min(AppRetData[:,1]), 0.5*(np.max(AppRetData[:,1])+np.min(AppRetData[:,1]))])
    ax2.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    ax2.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])

    ATemp = AppRetData_Detrended[locMinAppRet[0]:,0:2]
    ATemp = ATemp-[ATemp[0,0],ATemp[0,1]]
    
    ax3.plot(ATemp[:,0], ATemp[:,1], 'o')
    ax3.plot(pwlfit[:,0], pwlfit[:,1], '-k')
    ax3.axvline(x=ATemp[ZeroPointIndex,0], color='r', linestyle='--')
    ax3.set_title('Approach Curve', fontsize=fontfeatures['TitleFontSize'])
        
    RTemp = AppRetData_Detrended[:locMinAppRet[1],2:4]
    ax4.plot(RTemp[:,0], RTemp[:,1], 'or')
    ax4.set_title('Retract Curve', fontsize=fontfeatures['TitleFontSize'])
    
    if afmUsed.partition('_')[0]=='Bruker':
        ax1.set_ylabel('Cant. deflection (V)',fontsize=fontfeatures['xylabelFontSize'])
        ax2.set_ylabel('Cant. deflection (V)',fontsize=fontfeatures['xylabelFontSize'])        
        ax3.set_ylabel('Cant. deflection (V)',fontsize=fontfeatures['xylabelFontSize'])
        ax3.set_xlabel('Piezo Disp. (nm)',fontsize=fontfeatures['xylabelFontSize'])
        ax4.set_xlabel('Piezo Disp. (nm)',fontsize=fontfeatures['xylabelFontSize'])
        ax3.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        ax4.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])        
    elif afmUsed.partition('_')[0]=='Asylum':
        if afmUsed.partition('_')[2]=='DD':
            ax1.set_ylabel('Cant. deflection (nm)',fontsize=fontfeatures['xylabelFontSize'])
            ax2.set_ylabel('Cant. deflection (nm)',fontsize=fontfeatures['xylabelFontSize'])          
            ax3.set_ylabel('Cant. deflection (nm)',fontsize=fontfeatures['xylabelFontSize'])
            ax3.set_xlabel('Piezo Disp. (nm)',fontsize=fontfeatures['xylabelFontSize'])
            ax4.set_xlabel('Piezo Disp. (nm)',fontsize=fontfeatures['xylabelFontSize'])
            ax3.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
            ax4.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize']) 
        elif afmUsed.partition('_')[2]=='VD':
            ax1.set_ylabel('Cant. deflection (V)',fontsize=fontfeatures['xylabelFontSize'])
            ax2.set_ylabel('Cant. deflection (V)',fontsize=fontfeatures['xylabelFontSize'])          
            ax3.set_ylabel('Cant. deflection (V)',fontsize=fontfeatures['xylabelFontSize'])
            ax3.set_xlabel('Piezo Disp. (nm)',fontsize=fontfeatures['xylabelFontSize'])
            ax4.set_xlabel('Piezo Disp. (nm)',fontsize=fontfeatures['xylabelFontSize'])
            ax3.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
            ax4.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])               
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(directory,'Plt_AFMData-Corrs_Test_'+str(filenum+1)+'_'+sampName), dpi=300, bbox_inches='tight')  
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(directory,'Plt_AFMData-Corrs_Test_'+str(filenum+1)+'_'+sampName+'.svg'), format = 'svg')       
    axss = [ax1, ax2, ax3, ax4]
    return  axss
