#Interactive MultiStep CycleIndetifier############################################################################################################################################################
def NumberofCyclesConfirmation(ncyc, array, extremepnts, instrused, fontfeatures):
    root = tk.Tk()
    root.title("Cycle Identification")
    root.configure(bg='white')
    root.withdraw()
    # Create a label with the number of cycles
    label_frame = tk.Frame(root, bg='white')
    label_frame.pack(padx=10, pady=(10, 0))
    label_text = tk.Label(label_frame, text="SpherIndent has identified: " + str(ncyc) + ' cycles', bg='white', font=('12'))
    label_text.pack(side=tk.LEFT)
    # Create a plot
    plot_frame = tk.Frame(root, bg='white')
    plot_frame.pack(padx=10, pady=(0, 10))
    fig = Figure(figsize=(6, 4), dpi=100)
    ax = fig.add_subplot(111)
    if instrused=='IIT':
        ax.plot(array[:,2],'k', label='Raw Data')
        ax.plot(extremepnts, array[extremepnts,2],'x', label='Segment Points')
        ax.set_xlabel('Index', fontsize=fontfeatures['xylabelFontSize'])
        ax.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize']) 
    elif instrused=='AFM':  
        ax.plot(array[:,1],'k', label='Raw Data')
        ax.plot(extremepnts, array[extremepnts,1],'x', label='Segment Points')
        ax.set_xlabel('Index', fontsize=fontfeatures['xylabelFontSize'])
        ax.set_ylabel('Force (nN)', fontsize=fontfeatures['xylabelFontSize'])                  
    ax.legend(loc="upper left", fontsize=fontfeatures['legendFontSize']) 
    ax.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    canvas = FigureCanvasTkAgg(fig, master=plot_frame)
    canvas.draw()
    canvas.get_tk_widget().pack()
    # Create a frame to hold the buttons
    button_frame = tk.Frame(root, bg='white')
    button_frame.pack(padx=10, pady=10)
    # Define a dictionary to map button clicks to flag values
    flag_values = {
        "Undercounting": -1,
        "Overcounting": 1,
        "Correct": 0
    }
    # Create a variable to store the flag value
    flag = tk.IntVar()
    flag.set(None)  # Initialize with None
    # Handle button clicks
    def on_button_click(value):
        flag.set(value)
        root.destroy()
    # Create the buttons
    for text, value in flag_values.items():
        button = tk.Button(button_frame, text=text, font=("Arial", 10, "bold"), command=lambda v=value: on_button_click(v))
        button.pack(side=tk.LEFT, padx=5)
    root.update_idletasks()
    center_window(root, root.winfo_width(), root.winfo_height()) 
    root.deiconify()         # Reveal the window now that it is centered
    root.attributes('-topmost', True) # Force window to the very front
    root.focus_force()       # Steal keyboard/mouse focus    
    # Start the Tkinter event loop
    root.wait_window()  # Wait for the window to be destroyed
    # Return the flag value
    return flag.get()
#FDCurveSegmentPlottersMultiStep##################################################################################################################################################################
def fdSegmentPlottersMultiStep(tdfarray, extremepoints, slopeDrift, ordinateDrift, idxDriftStart, goodnessDriftFit, 
                               driftcorrdisp, dfcorr, extremepointscorr, savefigdir, testnum, fontfeatures):
    fig = plt.figure(figsize=(12, 6.))
    fig.suptitle('Test ' + str(testnum))
    gs = GridSpec(2, 2, figure=fig)
    ax1 = fig.add_subplot(gs[:, 0])  
    ax2 = fig.add_subplot(gs[0, 1])
    ax3 = fig.add_subplot(gs[1, 1])
     
    ax1.plot(tdfarray[:,1],tdfarray[:,2],'k', label='Raw Data')
    ax1.plot(tdfarray[extremepoints,1],tdfarray[extremepoints,2],'.r',markersize=8)
    if not np.isnan(slopeDrift):
        ax1.plot(driftcorrdisp, tdfarray[:,2],'--k', label='Drift Corrected Data')
    ax1.plot(dfcorr[:,0], dfcorr[:,1],'--r', label='ZP & Mach. Comp. Corrected Data')
    ax1.plot(dfcorr[extremepointscorr,0],dfcorr[extremepointscorr,1],'.r',markersize=8)
    ax1.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax1.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax1.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    ax1.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])

    ax2.plot(tdfarray[:,2],'k', label='Raw Data')
    ax2.plot(extremepoints, tdfarray[extremepoints,2],'x', label='Segment Points')
    ax2.set_xlabel('Index', fontsize=fontfeatures['xylabelFontSize'])
    ax2.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax2.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    ax2.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    if not np.isnan(slopeDrift):      
        ax3.plot(tdfarray[extremepoints[-2]:,0],tdfarray[extremepoints[-2]:,1],'ok', label='Thermal Drift Data')
        ax3.plot(tdfarray[extremepoints[-2]+idxDriftStart,0],tdfarray[idxDriftStart+extremepoints[-2],1],'.r', label='Segment Points', markersize=8)
        ax3.plot(tdfarray[extremepoints[-2]+idxDriftStart:,0],slopeDrift*tdfarray[extremepoints[-2]+idxDriftStart:,0]+ordinateDrift, 
                label='Thermal Drift Data Fit(D='+str(round(slopeDrift,5))+'nm/s |'+r'$R^{2}$'+'='+str(round(goodnessDriftFit,3))+')')         
        ax3.set_xlabel('Time (s)', fontsize=fontfeatures['xylabelFontSize'])
        ax3.set_ylabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
        ax3.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
        ax3.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    else:
        ax3.plot(0.,0.,'ok', label='No Thermal Drift Data')        
        ax3.set_xlabel('Time (s)', fontsize=fontfeatures['xylabelFontSize'])
        ax3.set_ylabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
        ax3.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
        ax3.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])        
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'Plt_PhData-Corrs_Test_'+str(testnum)), dpi=300, bbox_inches='tight')  
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'Plt_PhData-Corrs_Test_'+str(testnum)+'.svg'), format = 'svg')       
    axss = [ax1, ax2, ax3]
    return  axss
#fdStressStrainPlottersMultiStep##################################################################################################################################################################
def fdStressStrainPlottersMultiStep(array, unloadfits, instrused, issmethod, savefigdir, testnum, fontfeatures):
    fig, axs = plt.subplots(1,3,figsize=(12, 6.))
    fig.suptitle('Test ' + str(testnum))    
    #Retrieve Data from Arrays
    if instrused=='IIT':
        dispplot=remove_nans(array[testnum,:,12],0)
        forceplot=remove_nans(array[testnum,:,13],0)
        extrpoints=remove_nans(array[testnum,:,14],0)
        extremepoints=extrpoints.astype(int)
        strainplot=remove_nans(array[testnum,:,15],0)
        stressplot=remove_nans(array[testnum,:,16],0)
        elastOrplastic=remove_nans(array[testnum,:,22],0)
        Emean=np.nanmean(array[testnum,:,18])  
    elif instrused=='AFM':
        dispplot=remove_nans(array[0,:,13],0)
        forceplot=remove_nans(array[0,:,14],0)
        extrpoints=remove_nans(array[0,:,19],0)
        extremepoints=extrpoints.astype(int)
        strainplot=remove_nans(array[0,1:,20],0)
        stressplot=remove_nans(array[0,1:,21],0)
        elastOrplastic=remove_nans(array[0,1:,27],0)
        Emean=np.nanmean(array[0,1:,23])        
    #Plotter
    axs[0].plot(dispplot,forceplot,'k', label='F-D Curve')
    axs[0].plot(dispplot[extremepoints],forceplot[extremepoints],'.r',markersize=6)
    axs[0].set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    if instrused=='IIT':
        axs[0].set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    elif instrused=='AFM':
        axs[0].set_ylabel('Force (nN)', fontsize=fontfeatures['xylabelFontSize'])
    axs[0].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    axs[0].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
 
    axs[1].plot(dispplot,forceplot,'k', label='F-D Curve')
    axs[1].plot(dispplot[extremepoints],forceplot[extremepoints],'.r',markersize=6)
    for p in range(0,int(0.5*unloadfits.shape[1])):
        if p==int(0.5*unloadfits.shape[1])-1:
            if 'Kalidindi' in issmethod:
                axs[1].plot(remove_nans(unloadfits[:,2*p],0),remove_nans(unloadfits[:,2*p+1],0),'--r', label='Hertz Fit')
            elif 'Field' in issmethod:
                if instrused=='IIT':
                    axs[1].plot(remove_nans(unloadfits[:,2*p],0),remove_nans(unloadfits[:,2*p+1],0),'--r', label='OP Fit')
        else:
            if 'Kalidindi' in issmethod:
                axs[1].plot(remove_nans(unloadfits[:,2*p],0),remove_nans(unloadfits[:,2*p+1],0),'--r')
            elif 'Field' in issmethod: 
                if instrused=='IIT':
                    axs[1].plot(remove_nans(unloadfits[:,2*p],0),remove_nans(unloadfits[:,2*p+1],0),'--r')
    axs[1].set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    if instrused=='IIT':
        axs[1].set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    elif instrused=='AFM':
        axs[1].set_ylabel('Force (nN)', fontsize=fontfeatures['xylabelFontSize'])
    axs[1].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    axs[1].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])

    #Plot stress-strain pairs based on elastic-plastic status
    elasticMask = (elastOrplastic == 0) 
    plasticMask = (elastOrplastic == 1) 
    if len(strainplot[elasticMask])>0:
        axs[2].plot(strainplot[elasticMask],stressplot[elasticMask],'sb', markersize=6, label='Elastic Stress-Strain Pairs')
    if len(strainplot[plasticMask])>0:
        axs[2].plot(strainplot[plasticMask],stressplot[plasticMask],'ob', markersize=6, label='Plastic Stress-Strain Pairs')   
    #OLS Regression
    olsE = LinearRegression(fit_intercept=False)
    if len(strainplot[elasticMask])>0:
        try:
            olsE.fit(strainplot[elasticMask].reshape(-1, 1), stressplot[elasticMask])
            Eiss = olsE.coef_[0] 
            y_pred_olsE = olsE.predict(strainplot[elasticMask].reshape(-1, 1))
            r2_olsE=r_squared(stressplot[elasticMask], y_pred_olsE)
            axs[2].plot(np.linspace(0,np.max(strainplot[elasticMask]),20), Eiss*np.linspace(0,np.max(strainplot[elasticMask]),20), 
                        color='blue', label=f'OLS Regression ($E={round(Eiss, 2)}$ GPa, $R^2={round(r2_olsE, 2)}$)')    
        except:
            Eiss = 0.
    else:
        Eiss = 0.
        axs[2].plot(np.linspace(0,1.1*np.max(strainplot),20),Emean*np.linspace(0,1.1*np.max(strainplot),20),'--k',label=f'Elastic Path (E={round(Emean, 2)} GPa)')
    olsP = LinearRegression()
    if len(strainplot[plasticMask])>0:
        try:
            olsP.fit(strainplot[plasticMask].reshape(-1, 1), stressplot[plasticMask])
            y_pred_olsP = olsP.predict(strainplot[plasticMask].reshape(-1, 1))
            r2_olsP=r_squared(stressplot[plasticMask], y_pred_olsP)
            yieldStrain_olsP = (-Emean*0.002-olsP.intercept_)/(olsP.coef_[0]- Emean)
            yieldStress_olsP = Emean*(yieldStrain_olsP-0.002)   
            plasSlope_olsP = olsP.coef_[0]
            if plasSlope_olsP>0:
                if yieldStress_olsP>0.:
                    yieldStrain = yieldStrain_olsP
                    yieldStress = yieldStress_olsP   
                    plasSlope = plasSlope_olsP
                    axs[2].plot(np.linspace(yieldStrain,np.max(strainplot),20), olsP.coef_*np.linspace(yieldStrain,np.max(strainplot),20)+olsP.intercept_, 
                                color='cyan', label=fr'OLS Regression ($\sigma_{{Y}}={round(yieldStress, 2)}$ GPa, $R^2={round(r2_olsP, 2)}$)')            
                    axs[2].plot(yieldStrain, yieldStress, 'rx',markersize=4) 
                else:
                    plasSlope=0.;yieldStrain=0.;yieldStress=0.
            else:
                plasSlope=0.;yieldStrain=0.;yieldStress=0.
        except:
            plasSlope=0.;yieldStrain=0.;yieldStress=0.
    else:
        plasSlope=0.;yieldStrain=0.;yieldStress=0.
    
    axs[2].set_xlabel('Indentation Strain', fontsize=fontfeatures['xylabelFontSize'])
    axs[2].set_ylabel('IndentationStress (GPa)', fontsize=fontfeatures['xylabelFontSize'])
    axs[2].set_xlim(left=0.0, right=1.5*np.max(strainplot))
    axs[2].set_ylim(bottom=-0.1, top=np.maximum(1.25*Emean*1.1*np.max(strainplot), np.max(stressplot)*1.1))
    axs[2].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    axs[2].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'IndentationCurve_Test_'+str(testnum)), dpi=300, bbox_inches='tight')   
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'IndentationCurve_Test_'+str(testnum)+'.svg'), format = 'svg')       
    return Emean, Eiss, plasSlope, yieldStrain, yieldStress, axs 
#fdHertzOPharrPlotter##################################################################################################################################################################
def fdHertzOPharrPlotter(dfcorr, loadEndCorrloc, holdEndCorrloc, unloadEndCorrloc, fittedloadforce, fittedunloadforce, modulusH, modulusOP, 
                         goodnessH, goodnessOP, opfitconstants, eeff, radiustip, shearstress, popins, saveimgdir, testnum, act, sampName, fontfeatures):
    fig, axs = plt.subplots(1, 1, figsize=(6, 6))
    axs.plot(dfcorr[:loadEndCorrloc+1,0], dfcorr[:loadEndCorrloc+1,1],'or', markersize=2)    
    axs.plot(dfcorr[loadEndCorrloc:unloadEndCorrloc+1,0], dfcorr[loadEndCorrloc:unloadEndCorrloc+1,1],'or', label='Exp. Data', markersize=2, alpha=0.5)   
    if 'Advanced' in act:
        axs.plot(fittedloadforce[:,0], fittedloadforce[:,1],'--k', 
                 label='Hertz Fit(' + r'$E_{sample}$'+'='+str(round(modulusH,1))+' GPa, τ='+str(round(shearstress,2))+' GPa, ' +r'$R^{2}$'+'='+str(round(goodnessH,2))+')')        
        axs.plot(dfcorr[:loadEndCorrloc+1,0], (1e-6)*(4/3)*eeff*((radiustip)**(1/2))*(dfcorr[:loadEndCorrloc+1,0])**(3/2),'-k',alpha=0.5)
    else:
        axs.plot(fittedloadforce[:,0], fittedloadforce[:,1],'--k', 
                 label='Hertz Fit(' + r'$E_{sample}$'+'='+str(round(modulusH,1))+' GPa |' +r'$R^{2}$'+'='+str(round(goodnessH,2))+')')
    if popins.shape[0]!=0:
        axs.plot(popins[:,0],popins[:,1],'kx',markersize=2)
    axs.set_ylim(bottom=-0.01, top=1.1*dfcorr[loadEndCorrloc,1])
    axs.plot(fittedunloadforce[:,0], fittedunloadforce[:,1],'--k', 
             label='O-P Fit(A=' +str(round(opfitconstants[0]*1000,2)) + 'mN,'+ r'$h_{f}$' + '=' +
             str(round(opfitconstants[1],2))+'nm,m=' + str(round(opfitconstants[2],2))+'\n' + r'$E_{sample}$'+'='+
             str(round(modulusOP,1))+' GPa,' +r'$R^{2}$'+'='+str(round(goodnessOP,2))+')')        
    axs.set_title('Test '+str(testnum), fontsize=fontfeatures['TitleFontSize'])
    axs.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    axs.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])  
    axs.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.savefig(os.path.join(os.path.dirname(saveimgdir),'Plt_PhData-Fits_Test_'+str(testnum+1)+sampName), dpi=300, bbox_inches='tight') 
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(saveimgdir),'Plt_PhData-Fits_Test_'+str(testnum+1)+sampName+'.svg'), format = 'svg') 
    manager = fig.canvas.manager
    if hasattr(manager, 'window'):
        backend_window = manager.window
        backend_window.withdraw()
        width = int(fig.bbox.width)
        height = int(fig.bbox.height)
        center_window(backend_window, width, height)
        backend_window.deiconify()
        backend_window.attributes('-topmost', True)
        backend_window.attributes('-topmost', False)
        backend_window.focus_force()
    plt.show(block=False)
    fig.canvas.flush_events()
    return  fig, axs
def fdAFMHertzOPharrPlotter(fdcurveUncorr, idxstartunload, idxendunload, idxstartload, idxendload, pinsflag, popinsUncorr,
                            dfcorr, loadEndCorrloc, unloadEndCorrloc, fittedloaddispforce, fittedunloaddispforce, modulusH, modulusOP, 
                            goodnessH, goodnessOP, opfitconstants, eeff, radiustipOP, radiustipH, shearstress, popins, saveimgdir, testnum, 
                            act, sampName, fontfeatures):
    fig, axs = plt.subplots(1, 2, figsize=(16, 7))
    axs[0].plot(fdcurveUncorr[:,0],fdcurveUncorr[:,1],'r',label='AFM Curve (Raw)')
    if pinsflag==0:
        axs[0].plot(fdcurveUncorr[int(idxendload),0],fdcurveUncorr[int(idxendload),1],'ob',label='Fit Limit', markersize=3)
        axs[0].vlines(fdcurveUncorr[int(idxendload),0],0,fdcurveUncorr[int(idxendload),1], color='grey',linestyle='dotted')
    else:
        axs[0].plot(popinsUncorr[:,0],popinsUncorr[:,1],'dk',markersize=2)
        axs[0].plot(fdcurveUncorr[int(idxendload),0],fdcurveUncorr[int(idxendload),1],'ob',label='Elastic Limit', markersize=3)
        axs[0].vlines(fdcurveUncorr[int(idxendload),0],0,fdcurveUncorr[int(idxendload),1], color='grey',linestyle='dotted')
    axs[0].plot(fdcurveUncorr[int(idxstartunload),0],fdcurveUncorr[int(idxstartunload),1],'ob', markersize=3)
    axs[0].plot(fdcurveUncorr[int(idxendunload),0],fdcurveUncorr[int(idxendunload),1],'ob', markersize=3)
    if pinsflag==1:
        axs[0].plot(fittedloaddispforce[:,0]+fdcurveUncorr[int(idxstartload),0],
                    fittedloaddispforce[:,1]+fdcurveUncorr[int(idxstartload),1],'--k',
                    label=fr'Hertz Fit($E_{{sample}}={round(modulusH,1)}$ GPa, $R_{{ind}}={round(radiustipH,1)}$ nm, $R^{{2}}={round(goodnessH,2)}$)')
    else:
        axs[0].plot(fittedloaddispforce[:,0]+fdcurveUncorr[int(idxstartload),0],
                    fittedloaddispforce[:,1]+fdcurveUncorr[int(idxstartload),1],'--k',
                    label=fr'Hertz Fit($E_{{sample}}={round(modulusH,1)}$ GPa, $R_{{ind}}={round(radiustipH,1)}$ nm, $R^{{2}}={round(goodnessH,2)}$)')
    axs[0].plot(fittedunloaddispforce[:,0],
                fittedunloaddispforce[:,1],'--k',
                label=fr'O-P Fit(A={round(opfitconstants[0],2)} $mN^{{{round(opfitconstants[2],2)}}}$,$h_{{f}}={round(opfitconstants[1],2)}$nm' + '\n' + \
                    fr'$E_{{sample}}={round(modulusOP,1)}$ GPa, $R_{{ind}}={round(radiustipOP,1)}$ nm, $R^{{2}}={round(goodnessOP,2)}$)')
    axs[0].set_ylim(bottom=-0.01, top=1.1*np.max(fdcurveUncorr[:,1]))
    axs[0].set_title('Test '+str(testnum), fontsize=fontfeatures['TitleFontSize'])
    axs[0].set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    axs[0].set_ylabel('Force (nN)', fontsize=fontfeatures['xylabelFontSize'])
    axs[0].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])  
    axs[0].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[1].plot(dfcorr[:loadEndCorrloc+1,0], dfcorr[:loadEndCorrloc+1,1],'or', markersize=2)    
    axs[1].plot(dfcorr[loadEndCorrloc:unloadEndCorrloc+1,0], dfcorr[loadEndCorrloc:unloadEndCorrloc+1,1],'or', label='AFM Curve', markersize=2)   
    if pinsflag==1:
        axs[1].plot(fittedloaddispforce[:,0], fittedloaddispforce[:,1],'--k', 
                 label=fr'Hertz Fit($E_{{sample}}={round(modulusH,1)}$ GPa, $R_{{ind}}={round(radiustipH,1)}$ nm, $\tau_{{max}}={round(shearstress,1)}$ nm, $R^{{2}}={round(goodnessH,2)}$)')
        axs[1].plot(dfcorr[:loadEndCorrloc+1,0], (4/3)*eeff*((radiustipH)**(1/2))*(dfcorr[:loadEndCorrloc+1,0])**(3/2),'-k',alpha=0.5)
        axs[1].plot(popins[:,0],popins[:,1],'dk',markersize=2)
    else:
        axs[1].plot(dfcorr[int(loadEndCorrloc),0],dfcorr[int(loadEndCorrloc),1],'ob',label='Fit Limit', markersize=3)
        axs[1].plot(fittedloaddispforce[:,0], fittedloaddispforce[:,1],'--k', 
                 label=fr'Hertz Fit($E_{{sample}}={round(modulusH,1)}$ GPa, $R_{{ind}}={round(radiustipH,1)}$ nm, $R^{{2}}={round(goodnessH,2)}$)')
    axs[1].plot(fittedunloaddispforce[:,0]-fdcurveUncorr[int(idxstartload),0], fittedunloaddispforce[:,1]-fdcurveUncorr[int(idxstartload),1],'--k', 
                label=fr'O-P Fit(A={round(opfitconstants[0],2)} $mN^{{{round(opfitconstants[2],2)}}}$,$h_{{f}}={round(opfitconstants[1],2)}$nm' + '\n' + \
                    fr'$E_{{sample}}={round(modulusOP,1)}$ GPa, $R_{{ind}}={round(radiustipOP,1)}$ nm, $R^{{2}}={round(goodnessOP,2)}$)')     
    
    axs[1].set_ylim(bottom=-0.01, top=1.1*dfcorr[loadEndCorrloc,1])
    axs[1].set_title('Test '+str(testnum), fontsize=fontfeatures['TitleFontSize'])
    axs[1].set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    axs[1].set_ylabel('Force (nN)', fontsize=fontfeatures['xylabelFontSize'])
    axs[1].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])  
    axs[1].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])  
    plt.savefig(os.path.join(saveimgdir,'Plt_PhData-Fits_Test_'+str(testnum+1)+'_'+sampName), dpi=300, bbox_inches='tight') 
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(saveimgdir,'Plt_PhData-Fits_Test_'+str(testnum+1)+'_'+sampName+'.svg'), format = 'svg')
    manager = fig.canvas.manager
    if hasattr(manager, 'window'):
        backend_window = manager.window
        backend_window.withdraw()
        width = int(fig.bbox.width)
        height = int(fig.bbox.height)
        center_window(backend_window, width, height)
        backend_window.deiconify()
        backend_window.attributes('-topmost', True)
        backend_window.attributes('-topmost', False)
        backend_window.focus_force()
    plt.show(block=False)
    fig.canvas.flush_events()
    return  fig, axs
