##########BatchCalibrationSpecs####################################################################################################################################################################
def batchCalSpecifications():
    root = tk.Tk()
    root.title("Batch Calibration Specs")
    center_window(root, 300, 200)
    frame = tk.Frame(root)
    frame.pack(padx=10, pady=10)
    # Store the collected data
    batchCalSpecs = []
    # Create and grid the labels
    tk.Label(frame, text="Number of Reference Materials", font=("Arial", 10, "bold")).grid(row=0, column=0, padx=5, pady=5)
    tk.Label(frame, text="Number of Tuples", font=("Arial", 10, "bold")).grid(row=2, column=0, padx=5, pady=5)
    # Hold a persistent reference to the StringVar by attaching it to the frame
    frame.selected_value = tk.StringVar(root)
    dropdown = ttk.Combobox(frame, textvariable=frame.selected_value)
    dropdown['values'] = ('', '2', '3', '4')
    dropdown.current(0) # Default value
    dropdown.grid(row=1, column=0, padx=5, pady=5)
    entry = tk.Entry(frame)
    entry.grid(row=3, column=0, padx=5, pady=5)
    entry.insert(0, '100')  # Default value
    def on_next():
        # Retrieve the final value from the persistent reference
        batchCalSpecs.append((frame.selected_value.get(), entry.get()))
        root.destroy()
    def on_cancel():
        root.destroy()
    button_frame = tk.Frame(frame)
    button_frame.grid(row=4, column=0, columnspan=2, padx=5, pady=15)    
    next_button = tk.Button(button_frame, text="Next", font=("Arial", 10, "bold"), command=on_next)
    next_button.pack(side=tk.LEFT, padx=5)
    cancel_button = tk.Button(button_frame, text="Cancel", font=("Arial", 10, "bold"), command=on_cancel)
    cancel_button.pack(side=tk.LEFT, padx=5)
    root.wait_window()
    return batchCalSpecs    
def batchCalSpecificationsChudoba():
    root = tk.Tk()
    root.title("Batch Calibration Specs")
    center_window(root, 300, 300)
    frame = tk.Frame(root)
    frame.pack(padx=10, pady=10)
    frame2 = tk.Frame(root)
    frame2.pack(padx=10, pady=0)
    frame3 = tk.Frame(root)
    frame3.pack(padx=10, pady=0)
    # Store the collected data
    batchCalSpecs = []
    # Create and grid the labels
    tk.Label(frame, text="Number of Reference Materials", font=("Arial", 10, "bold")).grid(row=0, column=0, padx=5, pady=5)
    tk.Label(frame, text="Number of Tuples", font=("Arial", 10, "bold")).grid(row=2, column=0, padx=5, pady=5)
    tk.Label(frame2, text="Number of Max. Loads", font=("Arial", 10, "bold")).grid(row=4, column=0, padx=5, pady=5)
    # Hold a persistent reference to the StringVar by attaching it to the frame
    frame.selected_value = tk.StringVar(root)
    dropdown = ttk.Combobox(frame, textvariable=frame.selected_value)
    dropdown['values'] = ('', '2', '3', '4')
    dropdown.current(0) # Default value
    dropdown.grid(row=1, column=0, padx=5, pady=5)
    entry = tk.Entry(frame)
    entry.grid(row=3, column=0, padx=5, pady=5)
    entry.insert(0, '100')  # Default value
    frame2.selected_value = tk.StringVar(root)
    dropdown2 = ttk.Combobox(frame2, textvariable=frame2.selected_value)
    dropdown2['values'] = ('','1', '2', '3', '4')
    dropdown2.current(0) # Default value
    dropdown2.grid(row=5, column=0, padx=5, pady=5)
    def on_next():
        # Retrieve the final value from the persistent reference
        batchCalSpecs.append((frame.selected_value.get(), entry.get(), frame2.selected_value.get()))
        root.destroy()
    def on_cancel():
        root.destroy()
    button_frame = tk.Frame(frame3)
    button_frame.grid(row=6, column=0, columnspan=2, padx=5, pady=25)    
    next_button = tk.Button(button_frame, text="Next", font=("Arial", 10, "bold"), command=on_next)
    next_button.pack(side=tk.LEFT, padx=5)
    cancel_button = tk.Button(button_frame, text="Cancel", font=("Arial", 10, "bold"), command=on_cancel)
    cancel_button.pack(side=tk.LEFT, padx=5)
    root.wait_window()
    return batchCalSpecs  
