def directCalInputPrompt():
    root = tk.Tk()
    root.title("Direct Calibration Input")
    center_window(root, 295, 150)
    tk.Label(root, text="Tip Radius\n(nm)", font=("Arial", 10)).grid(row=0, column=0, padx=15, pady=(15, 5))
    entry1 = tk.Entry(root, width=15)
    entry1.grid(row=1, column=0, padx=15, pady=5)
    entry1.insert(0, "0.0")    
    tk.Label(root, text="Single Compliance Value\n(nm/mN)", font=("Arial", 10)).grid(row=0, column=1, padx=15, pady=(15, 5))
    entry2 = tk.Entry(root, width=15)
    entry2.grid(row=1, column=1, padx=15, pady=5)
    entry2.insert(0, "0.0")   
    dircalinputs = []    
    def submitCalEntries():
        try:
            fl1radius = float(entry1.get())
            fl2compl = float(entry2.get())
            dircalinputs.append((fl1radius, fl2compl))
            root.destroy()
        except ValueError:
            pass         
    # Buttons Sub-Frame
    button_frame = tk.Frame(root)
    button_frame.grid(row=2, column=0, columnspan=2, pady=20)
    tk.Button(button_frame, text="Next", command=submitCalEntries, font=("Arial", 10, 'bold'), padx=10).pack(padx=5)
    root.wait_window()
    return dircalinputs if dircalinputs else None
