def getDataFile4Calibration(indx):
    root = tk.Tk()
    root.withdraw()
    if indx==0:
        file_path = filedialog.askopenfilename(title="Select 1st File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    elif indx==1:
        file_path = filedialog.askopenfilename(title="Select 2nd File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    elif indx==2:     
        file_path = filedialog.askopenfilename(title="Select 3rd File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    elif indx==3:     
        file_path = filedialog.askopenfilename(title="Select 4th File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")]) 
    else:
        file_path = filedialog.askopenfilename(title="Select "+ str(indx) + "th File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    return file_path
##########CalibrationEffectiveRadiusPlotter#######################################################################################################################################################
def plotterEffectiveRadius(nFiles, fVector, hdiffVector, linfit, rad, Rgoodness, rindex, derivative, powerlawfit, RgoodnessPowerLaw, path, axname, selTests, 
                           fontfeatures):
    if nFiles==2:
        labelscombinations = list(combinations(list(range(3)),2))
        axname[0].plot(fVector**(2/3), hdiffVector, 'or', label = 'Exp. Points', markersize=2)
        axname[0].plot(fVector**(2/3), linfit, '--k', 
                       label = 'Fit('+r'$R_{eff}$'+'='+str(round(rad,2))+'nm | '+r'$R^{2}$'+'='+str(round(Rgoodness,3))+')')
        axname[0].set_xlabel(r'$P^{2/3}$'+'('+r'$mN^{2/3}$'+')',fontsize=fontfeatures['xylabelFontSize'])
        axname[0].set_ylabel(r'$h_{'+str(labelscombinations[rindex][0])+'}$' +'-' + r'$h_{'+str(labelscombinations[rindex][1])+'}$'+'(nm)',
                             fontsize=fontfeatures['xylabelFontSize'])
        axname[0].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
        axname[0].set_title('Pair: Material '+str(labelscombinations[rindex][0])+' - Material '+ str(labelscombinations[rindex][1]),
                            fontsize=fontfeatures['xylabelFontSize'])
        axname[0].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        axname[1].plot(fVector, derivative, 'or', label = 'Exp. Points', markersize=2)
        if RgoodnessPowerLaw>0.8:
            axname[1].plot(fVector, powerlawfit.x[0]*(fVector**powerlawfit.x[1])+powerlawfit.x[2], '--k', 
                           label = 'Fit('+r'$R^{2}$'+'='+str(round(RgoodnessPowerLaw,3))+')')
        axname[1].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize'])
        axname[1].set_ylabel(r'$R_{eff}$'+'(nm)',fontsize=fontfeatures['xylabelFontSize'])
        axname[1].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])   
        axname[1].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        plt.tight_layout()
        plt.tight_layout()
        plt.savefig(os.path.join(os.path.dirname(os.path.dirname(path)),'Plt_Calib_FitR'+'-'.join(map(str, selTests))), dpi=300, bbox_inches='tight') 
        plt.rcParams['svg.fonttype'] = 'none'
        plt.savefig(os.path.join(os.path.dirname(os.path.dirname(path)),'Plt_Calib_FitR'+'-'.join(map(str, selTests))+'.svg'), format = 'svg')              
        plt.close('all')      
    elif nFiles==3:
        labelscombinations = list(combinations(list(range(3)),2))
        axname[0,rindex].plot(fVector**(2/3), hdiffVector, 'or', label = 'Exp. Points', markersize=2)
        axname[0,rindex].plot(fVector**(2/3), linfit, '--k', 
                              label = 'Fit('+r'$R_{eff}$'+'='+str(round(rad,2))+'nm | '+r'$R^{2}$'+'='+str(round(Rgoodness,3))+')')
        axname[0,rindex].set_xlabel(r'$P^{2/3}$'+'('+r'$mN^{2/3}$'+')',fontsize=fontfeatures['xylabelFontSize'])
        axname[0,rindex].set_ylabel(r'$h_{'+str(labelscombinations[rindex][0])+'}$' +'-' + r'$h_{'+str(labelscombinations[rindex][1])+'}$'+'(nm)',
                                    fontsize=fontfeatures['xylabelFontSize'])
        axname[0,rindex].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
        axname[0,rindex].set_title('Pair: Material '+str(labelscombinations[rindex][0])+' - Material '+ str(labelscombinations[rindex][1]),
                                   fontsize=fontfeatures['xylabelFontSize'])            
        axname[0,rindex].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        axname[1,rindex].plot(fVector, abs(derivative), 'or', label = 'Exp. Points', markersize=2)
        if RgoodnessPowerLaw>0.8:
            axname[1,rindex].plot(fVector, powerlawfit.x[0]*(fVector**powerlawfit.x[1])+powerlawfit.x[2], '--k', 
                                  label = 'Fit('+r'$R^{2}$'+'='+str(round(RgoodnessPowerLaw,3))+')')
        axname[1,rindex].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize'])
        axname[1,rindex].set_ylabel(r'$R_{eff}$'+'(nm)',fontsize=fontfeatures['xylabelFontSize'])
        axname[1,rindex].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
        axname[1,rindex].set_title('Pair: Material '+str(labelscombinations[rindex][0])+' - Material '+ str(labelscombinations[rindex][1]),
                                   fontsize=fontfeatures['xylabelFontSize'])  
        axname[1,rindex].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        plt.show()    
        if rindex==nFiles-1:
            plt.tight_layout()
            plt.savefig(os.path.join(os.path.dirname(os.path.dirname(path)),'Plt_Calib_FitR'+'-'.join(map(str, selTests))), dpi=300, 
                        bbox_inches='tight') 
            plt.rcParams['svg.fonttype'] = 'none'
            plt.savefig(os.path.join(os.path.dirname(os.path.dirname(path)),'Plt_Calib_FitR'+'-'.join(map(str, selTests))+'.svg'), 
                        format = 'svg')              
            plt.close('all')
