def chudobaPlotter(array,nloadlevels, direcsave, mater, fontfeatures):
    matsUsed = [item.split('-')[1].split('(')[0] for item in mater]
    fig, axs = plt.subplots(1, 4,figsize=(12, 6.))
    for b in range(0,nloadlevels): 
        axs[0].plot(remove_nans(array[b+1,:,0],0),remove_nans(array[b+1,:,1],0),'o', label='Load Level '+str(int(b+1)), markersize=4)
        axs[1].plot(remove_nans(array[b+1,:,0],0),remove_nans(array[b+1,:,2],0),'o', label='Load Level '+str(int(b+1)), markersize=4)
    axs[0].plot(remove_nans(array[0,:,0],0),remove_nans(array[0,:,1],0),'dk', label='Average',markersize=6)
    axs[1].plot(remove_nans(array[0,:,0],0),remove_nans(array[0,:,2],0),'dk', label='Average',markersize=6)
    axs[0].set_title('Tuple Materials: '+'-'.join(map(str, matsUsed)),fontsize=fontfeatures['xylabelFontSize'])
    axs[1].set_title('Tuple Materials: '+'-'.join(map(str, matsUsed)),fontsize=fontfeatures['xylabelFontSize'])
    axs[0].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize'])
    axs[1].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[0].set_ylabel(r'$R(nm)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[1].set_ylabel(r'$C(nm/mN)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[0].tick_params(axis='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[1].tick_params(axis='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[0].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    axs[1].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    maxForceLabels = np.unique(remove_nans(array[0, :, 0],0))
    violinDataR = [remove_nans(array[i+1, :, 1],0) for i in range(array.shape[0]-1)]
    meansR = [np.mean(y) for y in violinDataR]
    violinDataC = [remove_nans(array[i+1, :, 2],0) for i in range(array.shape[0]-1)]
    meansC = [np.mean(y) for y in violinDataC]
    axs[2].violinplot(violinDataR, showmeans=True)
    axs[2].plot(range(1, len(maxForceLabels) + 1), meansR, 'o--', color='red', markersize=4, lw=1)
    axs[3].violinplot(violinDataC, showmeans=True)
    axs[3].plot(range(1, len(maxForceLabels) + 1), meansC, 'o--', color='red', markersize=4, lw=1)
    axs[2].set_title('Tuple Materials: '+'-'.join(map(str, matsUsed)),fontsize=fontfeatures['xylabelFontSize'])
    axs[3].set_title('Tuple Materials: '+'-'.join(map(str, matsUsed)),fontsize=fontfeatures['xylabelFontSize'])
    axs[2].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize'])
    axs[3].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[2].set_ylabel(r'$R(nm)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[3].set_ylabel(r'$C(nm/mN)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[2].tick_params(axis='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[3].tick_params(axis='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[2].set_xticks(range(1, len(maxForceLabels) + 1), maxForceLabels)
    axs[3].set_xticks(range(1, len(maxForceLabels) + 1), maxForceLabels)
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(direcsave),'Plt_RadiusComplFun_'+'-'.join(map(str, matsUsed))), dpi=300, bbox_inches='tight') 
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(direcsave),'Plt_RadiusComplFun_'+'-'.join(map(str, matsUsed))+'.svg'), format = 'svg')      
    return axs   
