    ax1 = fig.add_subplot(gs[0, 1])
    ax2 = fig.add_subplot(gs[0, 2])
    ax3 = fig.add_subplot(gs[1, 1])
    ax4 = fig.add_subplot(gs[1, 2])
    ax5 = fig.add_subplot(gs[:, 3])
    ax0.plot(depthcircles,circfits[:,2],'-ok',markersize=5, label='Local Radius')
    ax0.plot(depthcircles,np.mean(circfits[:,2])*np.ones(circfits.shape[0]),'--k', label='Mean Radius =' + str(round(np.mean(circfits[:,2]),1))+'nm')
