#AverageIndentationCurvePlotter###################################################################################################################################################################
def AverageIndentationCurvePlotter(x, y, stddev, xx, yy, stddevv, dunits, funits, sampName, save2dir, fontfeatures):
    fig, axs = plt.subplots(1, 1, figsize=(6, 6))
    axs.plot(x, y, '-b', label='Mean F-D Curve')
    axs.plot(xx, yy, '-b')
    axs.fill_betweenx(y, x - stddev, x + stddev, color='gray', alpha=0.5, label='Mean ± Std Dev')
    axs.fill_betweenx(yy, xx - stddevv, xx + stddevv, color='gray', alpha=0.5, label='Mean ± Std Dev')
    axs.set_xlabel('Indentation Depth ('+ dunits +')',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylabel('Force ('+ funits +')',fontsize=fontfeatures['xylabelFontSize'])
    axs.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])  
    axs.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join((os.path.dirname(save2dir)),'Plt_AvgPhData_'+sampName), dpi=300, bbox_inches='tight') 
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join((os.path.dirname(save2dir)),'Plt_AvgPhData_'+sampName+'.svg'), format = 'svg')  
    return axs     
#ModulusBarChartPlotter###########################################################################################################################################################################
def ModulusBarChartPlotter(EHertz, EOliverPharr, ERef, sampName, save2dir, fontfeatures):
    fig, axs = plt.subplots(1, 1, figsize=(6, 6))
    n = len(EHertz)
    # Set width of bar
    bar_width = 0.35
    # Set position of bar on X axis
    r1 = np.arange(n)
    r2 = [i + bar_width for i in r1] 
    errorHertz = (np.mean(EHertz) - ERef)/ERef
    errorOP = (np.mean(EOliverPharr) - ERef)/ERef
    axs.bar(r1, EHertz, color='b', width=bar_width, edgecolor='grey', 
            label='Hertz ('+r'$E_{Avg}$'+'='+str(round(np.mean(EHertz),2))+' ± '+str(round(np.std(EHertz),2))+' GPa, ε = '+str(round(errorHertz*100,2))+'%)')    
    axs.bar(r2, EOliverPharr, color='r', width=bar_width, edgecolor='grey',
            label='Oliver-Pharr ('+r'$E_{Avg}$'+'='+str(round(np.mean(EOliverPharr),2))+' ± '+str(round(np.std(EOliverPharr),2))+' GPa, ε = '+ str(round(errorOP*100,2))+'%)')
    axs.axhline(y=np.mean(EHertz), color='b', linestyle='--') 
    axs.axhline(y=np.mean(EOliverPharr), color='r', linestyle='--')  
    axs.set_xlabel('Test',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylabel('Modulus (GPa)',fontsize=fontfeatures['xylabelFontSize'])
    # Add xticks on the middle of the group bars
    axs.set_xticks([r + bar_width/2 for r in range(n)], np.arange(n)+1)
    axs.tick_params(axis='both', which='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])    
    axs.legend(fontsize=fontfeatures['xylabelFontSize'],loc='lower left')    
    plt.tight_layout()
    plt.show() 
    plt.savefig(os.path.join((os.path.dirname(save2dir)),'Plt_AvgModuli_'+sampName), dpi=300, bbox_inches='tight')
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join((os.path.dirname(save2dir)),'Plt_AvgModuli_'+sampName+'.svg'), format = 'svg')
    return axs    
#YieldCurvePlotter################################################################################################################################################################################
def yieldPlotter(issAll, avgESlope, avgEiss, avgPSlope, avgyieldStrain, avgyieldStress, elastModAll, elastModIss, yieldStressAll, nrows, sampName, directory, fontfeatures):
    #Define Matrix for all derived quantities
    AnalysisRepo = np.full((nrows,9),np.nan)
    #Plot 1
    fig, axs = plt.subplots(figsize=(6, 6)) 
    if len(issAll[issAll[:, 3]==0,0])>0:
        axs.plot(issAll[issAll[:, 3]==0,0],issAll[issAll[:,3]==0,1],'ok', markersize = 2, label = 'Elastic Pairs')
    if len(issAll[issAll[:, 3]==1,0])>0:
        axs.plot(issAll[issAll[:, 3]==1,0],issAll[issAll[:,3]==1,1],'dk', markersize = 2, label = 'Plastic Pairs')
    if len(issAll[issAll[:, 3]==0,0])>=4:  
        olsE = LinearRegression(fit_intercept=False)
        olsE.fit(issAll[issAll[:, 3]==0,0].reshape(-1, 1), issAll[issAll[:, 3]==0,1]) 
        r2_olsE=r_squared(issAll[issAll[:, 3]==0,1], olsE.predict(issAll[issAll[:, 3]==0,0].reshape(-1, 1)))
        strainElast = np.linspace(0, np.max(issAll[issAll[:, 3]==0,0]),10)     
        if r2_olsE>0.5:
            axs.plot(strainElast,olsE.coef_[0]*strainElast, '--k', label='Elastic Path ($E_{fit}=$'+str(round(olsE.coef_[0],2))+' GPa, $R^{2}$='+str(round(r2_olsE,2))+')')
            elasSlope = olsE.coef_[0]
        else:
            axs.plot(strainElast,avgESlope*strainElast, '--k', label='Elastic Path ($E_{avg}=$'+str(round(avgESlope,2))+' GPa)')
            elasSlope = avgESlope
    else:
        strainElast = np.linspace(0, np.max(issAll[:, 3]),10)
        axs.plot(strainElast,avgESlope*strainElast, '--k', label='Elastic Path ($E_{avg}=$'+str(round(avgESlope,2))+' GPa)')
        elasSlope = avgESlope
    if len(issAll[issAll[:, 3]==1,0])>=4: 
        olsP = LinearRegression()
        olsP.fit(issAll[issAll[:, 3]==1,0].reshape(-1, 1), issAll[issAll[:, 3]==1,1]) 
        r2_olsP=r_squared(issAll[issAll[:, 3]==1,1], olsP.predict(issAll[issAll[:, 3]==1,0].reshape(-1, 1)))
        if r2_olsP>0.5:
            yieldStrain = (-elasSlope*0.002-olsP.intercept_)/(olsP.coef_-elasSlope)    
            yieldStress = elasSlope*(yieldStrain-0.002)  
            strainPlast = np.linspace(yieldStrain, np.max(issAll[:, 3]),10)
            axs.plot(yieldStrain, yieldStress, 'rx',markersize=4) 
            axs.plot(strainPlast, olsP.coef_*strainPlast+olsP.intercept_, '--b',
                    label='Plastic Path ($H_{fit}$='+str(round(olsP.coef_[0],2))+' GPa, ' + '$σ_{Y, fit}$='+str(round(yieldStress[0],2))+' GPa, $R^{2}$='+str(round(r2_olsP,2))+')')
            plasSlope=olsP.coef_
        else:
            strainPlast = np.linspace(avgyieldStrain, np.max(issAll[:, 3]),10)
            ordP = avgyieldStress-avgPSlope*avgyieldStrain 
            axs.plot(avgyieldStrain, avgyieldStress, 'rx',markersize=4)
            axs.plot(strainPlast,avgPSlope*strainPlast+ordP, '--k', 
                     label='Plastic Path ($H_{avg}$='+str(round(avgPSlope,2))+' GPa, ' + '$σ_{Y, avg}$='+str(round(avgyieldStress,2))+' GPa)')
            yieldStress=avgyieldStress
            plasSlope=avgPSlope
    else:
            strainPlast = np.linspace(avgyieldStrain, np.max(issAll[:, 3]),10)
            ordP = avgyieldStress-avgPSlope*avgyieldStrain 
            axs.plot(avgyieldStrain, avgyieldStress, 'rx',markersize=4)
            axs.plot(strainPlast,avgPSlope*strainPlast+ordP, '--k', 
                     label='Plastic Path ($H_{avg}$='+str(round(avgPSlope,2))+' GPa, ' + '$σ_{Y, avg}$='+str(round(avgyieldStress,2))+' GPa)')         
            yieldStress=avgyieldStress
            plasSlope=avgPSlope
    axs.set_xlabel('Indentation Strain',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylabel('Indentation Stress (GPa)',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylim(bottom=-0.1, top=1.1*np.max(issAll[:,1]))
    axs.set_xlim(right=1.1*np.max(issAll[:,0]))
    axs.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])        
    axs.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show() 
    plt.savefig(os.path.join(directory,'YieldPlotter_'+sampName), dpi=300, bbox_inches='tight')
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(directory,'YieldPlotter_'+sampName+'.svg'), format = 'svg')    

    AnalysisRepo[0,0]=elasSlope
    AnalysisRepo[0,1]=plasSlope
    AnalysisRepo[0,2]=yieldStress

    #Yield Stress Histogram
    fig1, axs1 = plt.subplots(1,1,figsize=(6, 6.))
    sbn.histplot(yieldStressAll, kde=True, bins='auto', stat="percent", ax=axs1, color='r')
    axs1.axvline(x=yieldStress, color='black', linestyle='--', label='Mean')
    axs1.tick_params(axis='both', which='major', direction='in')
    axs1.set_xlabel('Yield Stress (GPa)',fontsize=10)
    axs1.set_ylabel('Percent (%)',fontsize=10)     
    plt.show        
    plt.savefig(os.path.join(directory,'Plt_Histo_YieldStress_'+sampName), dpi=300, bbox_inches='tight')
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(directory,'Plt_Histo_YieldStress_'+sampName+'.svg'), format = 'svg')
    AnalysisRepo [0:len(yieldStressAll),3]=yieldStressAll
    try: 
        kde_line = axs1.lines[-1]
        kde_x = kde_line.get_xdata()
        kde_y = kde_line.get_ydata()
        AnalysisRepo [0:len(kde_x),4] = kde_x 
        AnalysisRepo [0:len(kde_y),5] = kde_y 
    except:
        kde_x=np.nan
        kde_y=np.nan 
    #Elastic Modulus
    if np.all(elastModIss > 0):
        elastModforhist = elastModIss
    else:
        elastModforhist = elastModAll
    fig2, axs2 = plt.subplots(1,1,figsize=(6, 6.))
    sbn.histplot(elastModforhist, kde=True, bins='auto', stat="percent", ax=axs2, color='r')
    axs2.axvline(x=elasSlope, color='black', linestyle='--', label='Mean')
    axs2.tick_params(axis='both', which='major', direction='in')
    axs2.set_xlabel('Elastic Modulus (GPa)',fontsize=10)
    axs2.set_ylabel('Percent (%)',fontsize=10)     
    plt.show        
    plt.savefig(os.path.join(directory,'Plt_Histo_Elastic_'+sampName), dpi=300, bbox_inches='tight')
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(directory,'Plt_Histo_Elastic_'+sampName+'.svg'), format = 'svg') 
    AnalysisRepo [0:len(yieldStressAll),6]=elastModforhist
    try: 
        kde_line = axs2.lines[-1]
        kde_x = kde_line.get_xdata()
        kde_y = kde_line.get_ydata()
        AnalysisRepo [0:len(kde_x),7] = kde_x 
        AnalysisRepo [0:len(kde_y),8] = kde_y 
    except:
        kde_x=np.nan
        kde_y=np.nan
    return AnalysisRepo, [axs,axs1,axs2]        
#IndentMetricsPlotter#############################################################################################################################################################################
def IndentMetricsPlotter(numfiles, vars2plot, colindicesvars2plot, resultsArray, numrows, sampName, directory, fontfeatures):
    AnalysisRepo = np.full((numrows,3*len(vars2plot)),np.nan)
    colNames=[]
    axsContainer = [None]*len(vars2plot)
    for w in range(0,len(vars2plot)):
        VecZ = np.full((numfiles),np.nan)
        currVar = vars2plot[w]
        currindex = colindicesvars2plot[w]
        xlimits = None        
        match currVar:
            case 'HertzianSampleModulus':
                currVarshort='HertzE'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,1,currindex]
                cblabel = r'$E_{Hertz} (GPa)$' 
                title = 'Sample Modulus (Hertz)'            
            case 'NPopIns':
                currVarshort='NPIns'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,0,currindex]
                VecZ = np.nan_to_num(VecZ, nan=0)
                cblabel = r'$N_{Pop-Ins}$' 
                title = 'Number of Pop-In Events'
            case 'DissipativeIndex':
                currVarshort='DissIndx'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,0,currindex]
                cblabel = r'$\eta = 1-W_L/W_T$'
                title = 'Dissipative Index'
            case 'DissipationWork':
                currVarshort='DissW'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,0,currindex]
                cblabel = r'$W_d = W_L-W_U$ (pJ)'
                title = 'Dissipation Work'                
            case 'ExcursionLength':
                currVarshort='ExcLength'
                VecZ[:resultsArray.shape[0]]=abs(resultsArray[:,0,currindex])
                title = 'Displacement Burst'
                cblabel = r'$h_{p}-h_{e} (nm)$'  
            case 'HertzianGoodnessofFit':
                currVarshort='HertzR2'
                VecZ[:resultsArray.shape[0]]=np.array([resultsArray[i, ~np.isnan(resultsArray[i, :, currindex]), currindex][-1] 
                                                       for i in range(resultsArray.shape[0])])
                title = 'Goodness of Fit (Hertz)'
                cblabel = r'$R^2$' 
                #xlimits = (0.75*np.min(VecZ),1.25*np.max(VecZ))
        colNames.append(cblabel)                     
        fig, axs = plt.subplots(1,1,figsize=(6, 6.))
        sbn.histplot(VecZ, kde=True, bins='auto', stat="percent", ax=axs, color='r')
        axs.tick_params(axis='both', which='major', direction='in')
        axs.set_xlabel(cblabel, fontsize=fontfeatures['xylabelFontSize'])
        axs.set_ylabel('Percent (%)', fontsize=fontfeatures['xylabelFontSize'])  
        axs.set_title(title, fontsize=fontfeatures['TitleFontSize'])
        if xlimits is not None:
            axs.set_xlim(*xlimits)
        plt.show        
        plt.savefig(os.path.join(directory,'Plt_Histo_'+currVarshort+'_'+sampName), dpi=300, bbox_inches='tight')
        plt.rcParams['svg.fonttype'] = 'none'
        plt.savefig(os.path.join(directory,'Plt_Histo_'+currVarshort+'_'+sampName+'.svg'), format = 'svg') 
        #Retrieve Histrogram Data
        AnalysisRepo [0:len(VecZ),3*w] = VecZ 
        try: 
            kde_line = axs.lines[-1]
            kde_x = kde_line.get_xdata()
            kde_y = kde_line.get_ydata()
            AnalysisRepo [0:len(kde_x),3*w+1] = kde_x 
            AnalysisRepo [0:len(kde_y),3*w+2] = kde_y 
        except:
            kde_x=np.nan
            kde_y=np.nan
        axsContainer[w] = axs
    return AnalysisRepo, axsContainer
#PopInStatisticalAnalyzer#########################################################################################################################################################################
def PopInStatisticalAnalyzer(Array, indx2look):
    PopInsExp = np.vstack(Array[:,0,indx2look]).reshape(-1)
    sortedPopInStresses = np.sort(PopInsExp)
    cumDistrPopInStresses = np.cumsum(sortedPopInStresses) / np.sum(sortedPopInStresses)
    idxPopInStresses = (np.abs(cumDistrPopInStresses - 0.5)).argmin()
    return sortedPopInStresses, cumDistrPopInStresses, idxPopInStresses
#ECDFitter########################################################################################################################################################################################
def CumDistFunc(x, t, y):
    return (x[0]*t+x[1])-y
def gen_distr(t, slope, ordinate):      
    yfitted = 1-np.exp(-np.exp(slope*t+ordinate))
    return yfitted 
def ecdfitter(cumprobVector, xVector):  
    idxBot = np.abs(cumprobVector - 0.1).argmin()
    idxTop = np.abs(cumprobVector - 0.7).argmin()
    xecd_fit = xVector[idxBot:idxTop+1]
    yecd_fit = np.log(-1*np.log(1-cumprobVector[idxBot:idxTop+1]))
    ecd_lsq = least_squares(CumDistFunc, [1,-10] , args=(xecd_fit, yecd_fit))
    xfitrange = np.linspace(0.85*np.min(xVector), 1.15*np.max(xVector),50)
    fitdist = gen_distr(xfitrange,ecd_lsq.x[0],ecd_lsq.x[1])
    return xecd_fit, ecd_lsq.x[0], ecd_lsq.x[1], fitdist, xfitrange
#StatisticalPlotter###############################################################################################################################################################################   
def StatisticalPlotter(sortPopInStresses, cumDistrPopInStress, indxPopInStresses,xfit, fittdistr, fitparam1, fitparamr, sampname, directory, fontfeatures):
    fig, axs = plt.subplots(1,1,figsize=(6, 8.))   
    axs.plot(sortPopInStresses,cumDistrPopInStress,'.b', markerfacecolor="None")
    axs.plot([0.,sortPopInStresses[indxPopInStresses]],[cumDistrPopInStress[indxPopInStresses],cumDistrPopInStress[indxPopInStresses]],'--k')
    axs.plot([sortPopInStresses[indxPopInStresses],sortPopInStresses[indxPopInStresses]],[0.,cumDistrPopInStress[indxPopInStresses]],'--k')
    axs.plot(sortPopInStresses[indxPopInStresses],cumDistrPopInStress[indxPopInStresses],'ok', label = r'$\tau$' + r'$_{50}$' + ' = ' + 
             str(round(sortPopInStresses[indxPopInStresses],2))+' GPa (' + r'$\mu$' + '/' + str(round(44.6/sortPopInStresses[indxPopInStresses],1)) + ')')
    axs.plot(xfit,fittdistr,'-.k', label='Fitted ECD \n'+ r'$v^*$='+'{:.2e}'.format(fitparam1)+r'$nm^3$ ~'+ 
                str(round(fitparamr,1))+'Ω')
    axs.set_xlabel('Pop-In Shear Stress (GPa)',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_xlim(left=np.min(xfit),right=np.max(xfit))
    axs.set_ylabel('ECDF',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylim(bottom=-0.1, top=1.1)
    axs.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    axs.tick_params(axis='both', which='major', direction='in',labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show() 
    plt.savefig(os.path.join(os.path.dirname(directory),'Plt_ECDFShear_'+sampname), dpi=300, bbox_inches='tight')
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(directory),'Plt_ECDFShear_'+sampname+'.svg'), format = 'svg') 
    return axs 
#BSpline Fitter with Graded Knots################################################################################################################################################################
def gradedInternalKnots(x0,x1, x2, nseeds):
    #Normalize the values
    knots_left = x0 + (x1 - x0) * ((np.arange(1, nseeds//2))/(nseeds//2+1))**1.5
    knots_right = x1 + (x2 - x1) * ((np.arange(1, nseeds//2+1))/(nseeds//2+1))**2
    gradedKnots = np.concatenate((knots_left, [x1], knots_right))
    return np.sort(gradedKnots)
#PieceWiseFitter################################################################################################################################################################################
def fitpwPolyExp(x, y,peakIndex):
    x = np.array(x)
    y = np.array(y)
    # Find the peak
    xPeak = x[peakIndex]
    yPeak = y[peakIndex]
    # Split data
    xLeft, yLeft = x[:peakIndex+1], y[:peakIndex+1]
    xRight, yRight = x[peakIndex:], y[peakIndex:]
    # 3rd Deg Polynomial (ax^3 + bx^2 + cx + d)
    pCoeffs = np.polyfit(xLeft, yLeft, 3)
    # Exponential decay (y = plateau + (Peak - plateau) * exp(-k * (x - x_peak)))
    def expDecay(x, t, y, xpeak, ypeak):
            return (x[0] + (ypeak-x[0])*np.exp(-x[1]*(t-xpeak))) - y
    p0=[yRight[-1], 0.1]
    res = least_squares(expDecay, p0, args=(xRight, yRight, xPeak, yPeak), method='dogbox')
    popt = res.x
    return pCoeffs, popt
#CopyPasteCurveAverager############################################################################################################################################################################ 
def getTabularForceDispData(parent_window, crvetype, max_grid_size=5000):
    top = tk.Toplevel(parent_window)
    top.title("Excel Data Picker")
    top.geometry("700x500")
    displayText = "Excel Data Extractor"
    if crvetype == 'load':
        displayText = "Paste Loading Curves (Disp-Force)"
    elif crvetype == 'unload':
        displayText = "Paste Unloading Curves (Disp-Force)"
    titleLbl = tk.Label(top, text=displayText, font=("Arial", 14, "bold"), pady=10)
    titleLbl.pack()
    state = {"final_array": None, "data": None}
    # Function to paste data from clipboard
    def pasteData():
        try:
            rawData = top.clipboard_get()
            rowsData = [line.split('\t') for line in rawData.strip().split('\n')]
            state["data"] = rowsData
            if len(rowsData) * len(max(rowsData, key=len)) <= max_grid_size:
                for widget in grid_frame.winfo_children():
                    widget.destroy()
                state["entries"] = []
                for rIdx, rowList in enumerate(rowsData):
                    row_widgets = []
                    for cIdx, value in enumerate(rowList):
                        cell = tk.Entry(grid_frame, width=12)
                        cell.grid(row=rIdx, column=cIdx, padx=1, pady=1)
                        cell.insert(0, value)
                        row_widgets.append(cell)
                    state["entries"].append(row_widgets)
                grid_frame.pack(fill="both", expand=True, padx=10, pady=10)
                text_box.pack_forget()
            else:
                text_box.delete('1.0', tk.END)
                text_box.insert(tk.END, rawData)
                grid_frame.pack_forget()
                text_box.pack(fill="both", expand=True, padx=10, pady=10)
        except tk.TclError:
            pass
    # Function to process and exit
    def processAndExit():
        if state["data"] is not None and len(state["data"]) * len(max(state["data"], key=len)) <= max_grid_size:
            rawRows = [[cell.get() for cell in row] for row in state["entries"]]
            maxCols = max(len(row) for row in rawRows)
            padData = [row + [""] * (maxCols - len(row)) for row in rawRows]
            state["final_array"] = np.array(padData)
        elif state["data"] is not None:
            rawData = text_box.get('1.0', tk.END)
            rowsData = [line.split('\t') for line in rawData.strip().split('\n')]
            maxCols = max(len(row) for row in rowsData)
            padData = [row + [""] * (maxCols - len(row)) for row in rowsData]
            state["final_array"] = np.array(padData)
        top.destroy()
    # Toolbar
    toolbar = tk.Frame(top, pady=10)
    toolbar.pack(side="top", fill="x")
    btn_container = tk.Frame(toolbar)
    btn_container.pack(expand=True)
    tk.Button(btn_container, text="Proceed & Close", command=processAndExit, 
              bg="#808080", fg="white", font=("Arial", 10, "bold")
              ).pack(side="left", padx=10)
    tk.Button(btn_container, text="Paste from Excel", font=("Arial", 10, "bold"), command=pasteData
              ).pack(side="left", padx=10)
    # Grid definition
    grid_frame = tk.Frame(top)
    text_box = tk.Text(top)
    # Wait for window to close
    parent_window.wait_window(top)
    return state["final_array"]
def AveragingMethodPrompt():
    selectedMethod = [None]
    def next_button_clicked():
        selectedMethod[0] = combo.get()
        root.destroy()
    root = tk.Tk()
    root.title(" Averaging Method Selection")
    center_window(root, 360, 110)
    # Ensure columns expand evenly for true center alignment
    root.columnconfigure(0, weight=1)
    root.columnconfigure(1, weight=1)
    tk.Label(root, text="Averaging Method:").grid(row=0, column=0, padx=(15, 5), pady=15, sticky='e') 
    options = ['', 'Average Forces', 'Average Displacements']
    combo = ttk.Combobox(root, values=options, state="readonly", width=22)
    combo.current(0)  # Default selection ''
    combo.grid(row=0, column=1, padx=(5, 15), pady=15, sticky='w')
    btn = tk.Button(root, text="Next", font=("Arial", 10, "bold"), width=16, command=next_button_clicked)
    btn.grid(row=1, column=0, columnspan=2, pady=(0, 10))
    root.wait_window()
    return selectedMethod[0]
