##########CODESTARTER##############################################################################################################################################################################
def startCode():
    print("\033[H\033[J") 
    warnings.filterwarnings("ignore")
    plt.close('all')
    plt.ion()
    FontSizeSubplots={'axTicksFontSize':'8',
                      'xylabelFontSize': '9',
                      'legendFontSize': '8',
                      'TitleFontSize': '9'}
    FontSizeSinglePlots={'axTicksFontSize':'8',
                         'xylabelFontSize': '10',
                         'legendFontSize': '10',
                         'TitleFontSize': '10'}
    mpl.rcParams['font.family'] = 'Arial'
    nrows = 20000
    return FontSizeSubplots, FontSizeSinglePlots, nrows
##########CounterofStringswithSpecifiedSubstrings####################################################################################################################################################
def count_strings_with_substring(strings, substring):
    count = 0
    for string in strings:
        if string.startswith(substring):
            count += 1
    return count
##########NaN Remover################################################################################################################################################################################
def remove_nans(array, column_index):
    if array.ndim==1:
        return array[~np.isnan(array)]
    elif array.ndim==2:
        return array[~np.isnan(array[:, column_index])]
##########FileSorter################################################################################################################################################################################
def natkey(s):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r'(\d+)', s)]
#########NumericalIntegrator#########################################################################################################################################################################
def integrator(array):
    integralValue = np.trapz(array[:,1], array[:,0])
    return integralValue
#########R2Computer##################################################################################################################################################################################
def r_squared(y_true, y_pred):
    rss = np.sum((y_true - y_pred)**2)
    tss = np.sum((y_true - np.mean(y_true))**2)
    r2 = 1 - (rss / tss)
    return r2
#########PowerLawFitter##############################################################################################################################################################################
def PowerLawFitter(x, t, y):
    return (x[0]*(t**x[1])+x[2])-y   
#########DataFrame2PickleFileSaver###################################################################################################################################################################
def savedf2pickle(listdf, path_dir, act, mater):
    if 'PostprocessExperiments' in act.replace(" ", ""):
        file_path = path_dir + '/ExpResults_' + mater + '.pkl'
    elif 'CalibrateSphericalTip/MachineCompliance(IITOnly)_N≥2ReferenceMaterials[ChudobaMethod(2000)]' in act.replace(" ", ""):
        if any(isinstance(x, float) for x in mater):
            file_path = path_dir + '/Calib_TupleContainer_'+'-'.join(map(str, mater[:-1]))+'_'+str(int(mater[-1]))+'mN.pkl'
        else:
            matsUsed = [item.split('-')[1].split('(')[0] for item in mater]
            file_path = path_dir + '/Calib_TupleContainer_'+'-'.join(map(str, matsUsed))+'_ForAggregator.pkl'            
    elif 'CalibrateSphericalTip/MachineCompliance(IITOnly)_N≥2ReferenceMaterials[Li(2013)|Avadanii(2025)Methods]' in act.replace(" ", ""):
        file_path = path_dir + '/Calib_TupleContainer_'+'-'.join(map(str, mater))+'.pkl'               
    elif 'CalibrateSphericalTip/MachineCompliance(IITOnly)_CalibrationAggregator' in act.replace(" ", ""):
        file_path = path_dir + '/Calib_Master.pkl'
    elif 'CalibrateSphericalTip/MachineCompliance(IITOnly)_DirectInput' in act.replace(" ", ""):
        file_path = path_dir + '/Calibration_Master.pkl'
    elif 'AnalyzeIndenterTipImage_Choose' in act.replace(" ", ""):
        file_path = path_dir + '/AnalysedTipImage_'+ mater + '.pkl'
    elif 'AnalyzeResults_Basic' in act.replace(" ", "") or 'AnalyzeResults_Advanced' in act.replace(" ", ""):
        file_path = path_dir + '/AnalysedResults_'+ mater + '.pkl'
    elif 'AnalyzeResults_SimpleFDCurveAverager' in act.replace(" ", ""):
        file_path = path_dir + '/AverageForceDistCurves.pkl'
    elif 'AnalyzeResults_SimpleResidualSurfacesAverager' in act.replace(" ", ""):
        file_path = path_dir + '/AverageSurfResidualCurves.pkl'    
    elif 'AnalyzeResults_DamageDetector' in act.replace(" ", ""):
        file_path = path_dir + '/DamageDetectionAnalysis.pkl'                  
    try:
        with open(file_path, 'wb') as file:
            pickle.dump(listdf, file)
    except Exception as e:
        print(f"Error saving list of DataFrames: {e}")
