def spherIndentEngine(task):
    FontSizeSubplots, FontSizeSinglePlots, nRowsPreAlloc = startCode()
###################################################################################################################################################################################################      
####╔═╗╦╔╗╔╔═╗╦  ╔═╗  ╔═╗╔╦╗╔═╗╔═╗  ╔═╗╔═╗╔═╗╔╦╗╔═╗╦═╗╔═╗╔═╗╔═╗╔═╗╔═╗╔═╗╦═╗######################################################################################################################## 
####╚═╗║║║║║ ╦║  ║╣───╚═╗ ║ ║╣ ╠═╝  ╠═╝║ ║╚═╗ ║ ╠═╝╠╦╝║ ║║  ║╣ ╚═╗╚═╗║ ║╠╦╝######################################################################################################################## 
####╚═╝╩╝╚╝╚═╝╩═╝╚═╝  ╚═╝ ╩ ╚═╝╩    ╩  ╚═╝╚═╝ ╩ ╩  ╩╚═╚═╝╚═╝╚═╝╚═╝╚═╝╚═╝╩╚═######################################################################################################################## 
###################################################################################################################################################################################################      
    if 'PostprocessExperiments_Single-Step' in task.replace(" ", ""):
        if 'AFM' not in task.replace(" ", ""):
            instrumentUsed4Indentation = 'IIT'
            path2file = getDataFile4Analysis(instrumentUsed4Indentation)
            IITClass, path2calfile, nominalTipRadius_nm, timeAfterUnloadEnd4DriftCorr_sec, Temperature_K = IITInstrumentSelector(os.path.dirname(path2file))
            if len(path2calfile)!=0:
                calMachCompl, tipRadCal = retrieveDatafromCalibrationFile(path2calfile)
                #Check for existing pickle files in the same directory as the calibration file and the data file
                targetFilename = f"ExpResults_{os.path.basename(path2file).partition('_')[2].partition('_')[0]}.pkl"
                folders2search = [os.path.dirname(path2calfile), os.path.dirname(path2file)] if os.path.dirname(path2calfile) != os.path.dirname(path2file) else [os.path.dirname(path2file)]
                pickle_files = [os.path.join(f, targetFilename) for f in folders2search  if os.path.exists(os.path.join(f, targetFilename))]                
            else:
                usercalinputs = directCalInputPrompt()
                tipRadCal = usercalinputs[0][0]
                calMachCompl = usercalinputs[0][1]
                #Check for existing pickle files in the same directory as the data file only
                targetFilename = f"ExpResults_{os.path.basename(path2file).partition('_')[2].partition('_')[0]}.pkl"
                folders2search = [os.path.dirname(path2file)]            
                pickle_files = [os.path.join(f, targetFilename) for f in folders2search  if os.path.exists(os.path.join(f, targetFilename))]
            #Get elastic limit from user
            knownElasticLimit=elasticLimitSelector(1, [os.path.basename(path2file)], instrumentUsed4Indentation, task.replace(" ", ""))
            #Look up Poisson's Ratio or ask user to input
            tipMaterial = os.path.basename(path2file).partition('_')[0].partition('-')[2]
            sampleMaterial = os.path.basename(path2file).partition('_')[2].partition('_')[0].partition('-')[2]
            ETentative_Sample = retrieveRefProperties(sampleMaterial)[0]
            nuTentative_Sample = retrieveRefProperties(sampleMaterial)[1]
            EEstimated_Sample, poissonSample = SamplePropertiesPrompt(ETentative_Sample,nuTentative_Sample)
            peakprom = 0.01
            xlsFileSheets = pd.ExcelFile(path2file).sheet_names
            testSheets = sorted([sheet for sheet in xlsFileSheets if sheet.startswith('Test')])   
            nTests = len(testSheets)
            #Create ExpResults Matrix to store Results
            ExpResults = np.full((nTests, nRowsPreAlloc, 28), np.nan)
            df_Parameters = pd.DataFrame({'Number of Tests': [nTests],
                                        'IIT': [IITClass],  
                                        'ExperimentType': ['SingleStep'],
                                        'Sample': [os.path.basename(path2file).partition('_')[2].partition('_')[0]],
                                        'Tip': [os.path.basename(path2file).partition('_')[0]],
                                        'Tip Radius Nominal(nm)':[nominalTipRadius_nm],
                                        'Tip Radius Calibrated(nm)':[tipRadCal],
                                        'Modulus Tip(GPa)':[retrieveRefProperties(tipMaterial)[0]],
                                        'Poisson Tip':[retrieveRefProperties(tipMaterial)[1]],
                                        'Default Machine Compliance(nm/mN)':[0.],
                                        'Calibrated Machine Compliance(nm/mN)': [calMachCompl],
                                        'Temperature(K)':[Temperature_K]})
            if len(pickle_files)==0:
                path2saveDataPackage = os.path.dirname(path2file)
                Data_package = {'Readme': """This pickle file contains dataframes and figures with information from nanoindentation tests.""",
                'Dataframes': [],
                'Figures':[None]*(2*nTests)
                    }         
                Data_package["Dataframes"]=[pd.DataFrame() for _ in range(nTests+1)]
                Data_package["Dataframes"][0]=df_Parameters        
                #If file is newly created, save the data package to a pickle file in path2file directory      
                savedf2pickle(Data_package,path2saveDataPackage, task, os.path.basename(path2file).partition('_')[2].partition('_')[0])       
            else:
                path2saveDataPackage = os.path.dirname(pickle_files[0])
                #If file already exists, load the data package from the pickle file and update the parameters dataframe
                with open(path2saveDataPackage + '/ExpResults_'+os.path.basename(path2file).partition('_')[2].partition('_')[0]+'.pkl', 'rb') as pickle_files:
                    Data_package = pickle.load(pickle_files)
                    Data_package["Dataframes"][0]=df_Parameters
                savedf2pickle(Data_package,path2saveDataPackage, task, os.path.basename(path2file).partition('_')[2].partition('_')[0])       
            repeatFlag=False
            sequence=list(range(0,nTests))
            for k in sequence: 
                try:
                    plt.close('all')
                    print('Working on single-step indentation test ' + str(k)+' of '+str(nTests-1))
                    #Read Excel Sheet for Specific Test
                    dftemp = pd.read_excel(path2file, sheet_name=testSheets[k])
                    #Extract relevant columns, drop nans, remove duplicate rows
                    extracted_columns = dftemp[['Time On Sample', 'Displacement Into Surface', 'Load On Sample']].dropna(how='all')
                    tUnits, sUnits, fUnits = getUnits(extracted_columns)
                    #Convert dataframe to np.array
                    TimeDispForceArray = extracted_columns.drop(index=0).apply(pd.to_numeric).drop_duplicates().to_numpy()
                    #Determine the locations of the ends of the relevant segments
                    #Find local minima to determine L-H-UL cycles
                    peaksMinLoad, _ = find_peaks(-1*TimeDispForceArray[:,2], prominence=peakprom)
                    peaksMinLoad = np.insert(peaksMinLoad, 0, 0)
                    peaksMinLoad = np.insert(peaksMinLoad, len(peaksMinLoad), len(TimeDispForceArray[:,2])-1)        
                    nCycles = int(len(peaksMinLoad)-1)        
                    #Determine the locations of the ends of the relevant segments
                    points=[]
                    for n in range(0,nCycles):
                        st=peaksMinLoad[n]
                        loadEndcyc, holdEndcyc, unloadEndcyc = findLoadSegments(TimeDispForceArray[peaksMinLoad[n]:peaksMinLoad[n+1],[0,2]],peakprom)
                        if n<nCycles-1:
                            points.extend([st,peaksMinLoad[n]+loadEndcyc,peaksMinLoad[n]+holdEndcyc])
                        else:
                            points.extend([st,peaksMinLoad[n]+loadEndcyc,peaksMinLoad[n]+holdEndcyc,peaksMinLoad[n]+unloadEndcyc,peaksMinLoad[n+1]])
                    extrema = np.sort(np.array(points))        
                    loadEnd = extrema[1];holdEnd=extrema[2];unloadEnd=extrema[3]
                    loadRate = TimeDispForceArray[loadEnd,2]/TimeDispForceArray[loadEnd,0]
                    
                    #Thermal Drift Correction of Displacement
                    if timeAfterUnloadEnd4DriftCorr_sec > 0. :
                        driftRate, driftOrdinate, driftIndexStart, r2driftfit = thermalDriftCorr(TimeDispForceArray[unloadEnd:,:], timeAfterUnloadEnd4DriftCorr_sec)
                        corrDispTherm = TimeDispForceArray[:,1]-driftRate*TimeDispForceArray[:,0]
                    else:
                        driftRate, driftOrdinate, driftIndexStart, r2driftfit = np.nan, np.nan, np.nan, np.nan
                        corrDispTherm = TimeDispForceArray[:,1]
                    
                    #Correct Displacements for Machine Compliance
                    if len(path2calfile)!=0:
                        #Obtain Interpolation Function and Interpolate in the Force
                        fInterp = interp1d(calMachCompl[:,0], calMachCompl[:,1], kind='linear', fill_value=(calMachCompl[0,1], calMachCompl[-1,1]),bounds_error=False)
                        Cinterp = fInterp(TimeDispForceArray[:,2])
                        #Correct Thermal-Drift Displacements for Compliance
                        corrDisp = corrDispTherm -TimeDispForceArray[:,2]*Cinterp
                    else:
                        if calMachCompl !=0.:
                            #Correct Thermal-Drift Displacements for Compliance
                            corrDisp = corrDispTherm-TimeDispForceArray[:,2]*calMachCompl
                        else:
                            corrDisp = corrDispTherm

                    #DispForceCorr
                    DispForceCorrThMC = np.column_stack((corrDisp,TimeDispForceArray[:, 2]))

                    #Detect PopIns in the Force Displacement Approach Curve
                    FDCurveA = DispForceCorrThMC[0:loadEnd+1,:]
                    skipExpStatus=False
                    if ~np.isnan(knownElasticLimit[0]):
                        if ~np.isinf(knownElasticLimit[0]):
                            indxelasticLimit = np.argmin(abs(FDCurveA[:,1]-knownElasticLimit[0]))
                            AllPopInsUC = FDCurveA[indxelasticLimit,:].reshape(1, -1)
                        else:
                            AllPopInsUC=[]
                    else:
                        if repeatFlag==False:
                            FDPopIns = PopInDetection(FDCurveA)
                        else:
                            FDPopIns = AllPopInsUC 
                        #Binary Indicator for PopIn detection in the Force Displacement Approach Curve       
                        if FDPopIns.shape[0]!=0:
                            popInDetectionFlagFD=1
                        else:
                            popInDetectionFlagFD=0    
                        AllPopInsUC, skipExpStatus = PopInSelectionPlotter(popInDetectionFlagFD, FDCurveA, FDPopIns, DispForceCorrThMC, instrumentUsed4Indentation, FontSizeSinglePlots)
                    if skipExpStatus:                 
                        continue
                    #Binary Indicator for Overall PopIn detection in the Approach Curves
                    if len(AllPopInsUC)!=0:
                        popInDetectionFlag=1
                    else:
                        popInDetectionFlag=0 
                        AllPopInsUC=np.column_stack((np.inf,np.inf))
                    idx=[]
                    #Determine Range for Hertzian Fit 
                    if popInDetectionFlag==1:
                        for z in range(0,AllPopInsUC.shape[0]):
                            idx.append(np.abs(FDCurveA[:,0] - AllPopInsUC[z,0]).argmin())
                        x4fit = FDCurveA[:idx[0]+1,0]
                        y4fit = FDCurveA[:idx[0]+1,1]
                    else:
                        idx.append(np.abs(FDCurveA[:,1] - 0.9*FDCurveA[loadEnd,1]).argmin())
                        x4fit = FDCurveA[:idx[0]+1,0]
                        y4fit = FDCurveA[:idx[0]+1,1]
                    
                    #Retrieve the material properties of the tip    
                    moduliTip = df_Parameters['Modulus Tip(GPa)'].iloc[0]
                    poissonTip = df_Parameters['Poisson Tip'].iloc[0]
                    #Compute effective hertz modulus with an estimated sample modulus
                    EeffGuess = 1/((1-poissonTip**2)/moduliTip+(1-poissonSample**2)/EEstimated_Sample)
                    
                    #ZeroPoint Correction
                    approach='Pathak-Kalidindi'
                    if approach=='Pathak-Kalidindi':
                        best_R = None;best_x0 = None;best_B = None;min_cost = np.inf                             
                        # Iterate over each possible (x0, B) pair from the data
                        for i in range(idx[0]):
                            #Use every point in the curve as candidate for ZP
                            h0_candidate = x4fit[i]
                            p0_candidate = y4fit[i]*(1e6)                        
                            # Perform the least-squares optimization
                            res_lsq = least_squares(HertzianForceDepthFunctionUnknownEeffXYOffset, EeffGuess, args=(x4fit, y4fit*(1e6), h0_candidate, p0_candidate,tipRadCal),
                                                    bounds=([0.9*EeffGuess],[1.10*EeffGuess]))
                            # Check if this fit is better than previous ones
                            if res_lsq.cost < min_cost:
                                min_cost = res_lsq.cost
                                best_E = res_lsq.x[0]
                                best_h0 = h0_candidate
                                best_p0 = p0_candidate
                                best_ZPindx=i
                    #Correct the curves to account for Zero-Point
                    DispForceCorr = np.column_stack((DispForceCorrThMC[best_ZPindx:unloadEnd+1,0]-DispForceCorrThMC[best_ZPindx,0],
                                                    DispForceCorrThMC[best_ZPindx:unloadEnd+1,1]-DispForceCorrThMC[best_ZPindx,1]))
                    popInLocation = [x - best_ZPindx for x in idx if x >= best_ZPindx] 

                    if popInDetectionFlag==1:
                        AllPopIns = DispForceCorr[popInLocation,:]

                    loadEndCorr = loadEnd - best_ZPindx
                    holdEndCorr = holdEnd - best_ZPindx
                    unloadEndCorr = unloadEnd- best_ZPindx
                    
                    #Hertzian Fit Loading Section
                    if tipRadCal!=0.:
                        radius = tipRadCal
                    else:
                        radius = nominalTipRadius_nm
                    if popInDetectionFlag==1:           
                        FDCurveA = DispForceCorr[0:loadEndCorr+1,:]
                        idxTop=np.abs(AllPopIns[0,0]-DispForceCorr[:,0]).argmin()
                        DispForceCorrHertz=DispForceCorr[~(DispForceCorr[:,0] < 0)]
                        indshift = int(len(DispForceCorr[:,0])-len(DispForceCorrHertz[:,0]))                 
                        res_lsqH = least_squares(HertzianForceDepthFunctionUnknownEeff, np.array([EeffGuess]),
                                                args=(DispForceCorrHertz[0:idxTop-indshift+1,0], DispForceCorrHertz[0:idxTop-indshift+1,1], radius),
                                                bounds=([0.90*EeffGuess], [1.1*EeffGuess]))
                        fittedForce = (1e-6)*gen_ForceHertz1(DispForceCorrHertz[0:idxTop-indshift+1,0],res_lsqH.x[0], radius)        
                        r2H = r_squared(DispForceCorrHertz[0:idxTop-indshift+1,1], fittedForce)
                        moduliTip = df_Parameters['Modulus Tip(GPa)'].iloc[0]
                        poissonTip = df_Parameters['Poisson Tip'].iloc[0]            
                        indentModulusH = 1/((1/res_lsqH.x[0])-((1-poissonTip**2)/moduliTip))
                        sampleModulusH = indentModulusH*(1-poissonSample**2)              
                        HertzianFit = np.column_stack((DispForceCorrHertz[0:idxTop-indshift+1,0],fittedForce))
                        ContRadius = ((3/4)*((1e6)*DispForceCorrHertz[idxTop-indshift,1]*(radius*(1/res_lsqH.x[0]))))**(1/3)
                        tau = 0.31*(3/(2*math.pi*(ContRadius**2)))*(DispForceCorrHertz[idxTop-indshift,1]*(1e6))    
                        CumExcursionLength = abs(((3/4)*(1e6)*DispForceCorr[loadEndCorr,1]*(1/res_lsqH.x[0])*(1/(radius**0.5)))**(2/3)-DispForceCorr[loadEndCorr,0])
                    else:
                        AllPopIns=np.column_stack((np.inf,np.inf))
                        DispForceCorrHertz=DispForceCorr[~(DispForceCorr[:,0] < 0)]
                        fitshift = int(loadEndCorr - np.abs(DispForceCorr[:loadEndCorr+1,1]-0.95*DispForceCorr[loadEndCorr,1]).argmin())
                        indshift = int(len(DispForceCorr[:,0])-len(DispForceCorrHertz[:,0]))+fitshift            
                        res_lsqH = least_squares(HertzianForceDepthFunctionUnknownEeff, np.array([EeffGuess]),
                                                args=(DispForceCorrHertz[0:loadEndCorr-indshift+1,0], DispForceCorrHertz[0:loadEndCorr-indshift+1,1], radius),
                                                bounds=([0.], [np.inf]))
                        fittedForce = (1e-6)*gen_ForceHertz1(DispForceCorrHertz[0:loadEndCorr-indshift+1,0],res_lsqH.x[0], radius)           
                        r2H = r_squared(DispForceCorrHertz[0:loadEndCorr-indshift+1,1], fittedForce)
                        moduliTip = df_Parameters['Modulus Tip(GPa)'].iloc[0]
                        poissonTip = df_Parameters['Poisson Tip'].iloc[0]            
                        indentModulusH = 1/((1/res_lsqH.x[0])-((1-poissonTip**2)/moduliTip))
                        sampleModulusH = indentModulusH*(1-poissonSample**2)
                        HertzianFit = np.column_stack((DispForceCorrHertz[0:loadEndCorr-indshift+1,0],fittedForce))
                        ContRadius = ((3/4)*((1e6)*DispForceCorrHertz[loadEndCorr-indshift,1]*(radius*(1/res_lsqH.x[0]))))**(1/3)
                        tau = 0.31*(3/(2*math.pi*(ContRadius**2)))*(DispForceCorrHertz[loadEndCorr-indshift,1]*(1e6))
                        CumExcursionLength = abs(((3/4)*(1e6)*DispForceCorr[loadEndCorr,1]*(1/res_lsqH.x[0])*(1/(radius**0.5)))**(2/3)-DispForceCorr[loadEndCorr,0])
                    #Oliver-Pharr Unloading Analysis
                    indxXPercent = np.abs(DispForceCorr[holdEndCorr:unloadEndCorr+1,1]-0.8*DispForceCorr[holdEndCorr,1]).argmin()+holdEndCorr
                    indxXXPercent = np.abs(DispForceCorr[holdEndCorr:unloadEndCorr+1,1]-0.1*DispForceCorr[holdEndCorr,1]).argmin()+holdEndCorr
                    OPexplb=1.25;OPflag=0;OPexpInit=0.5*(OPexplb+2);lowTol=0.5;higTol=1.5
                    while OPflag==0:
                        res_lsqOlPharr = least_squares(OliverPharrUnloadingFunction, np.array([0.05,0.5*DispForceCorr[indxXXPercent,0],OPexpInit]),
                                                    args=(DispForceCorr[indxXPercent:indxXXPercent+1,0], DispForceCorr[indxXPercent:indxXXPercent+1,1]),
                                                bounds=([0,0,OPexplb], [np.inf,DispForceCorr[indxXXPercent,0],2]))
                        fittedUnloadForce = gen_ForceOlPharr(DispForceCorr[indxXPercent:indxXXPercent+1,0],res_lsqOlPharr)
                        fittedUnloadForcetoZero = gen_ForceOlPharr(np.linspace(1.01*res_lsqOlPharr.x[1],DispForceCorr[holdEndCorr,0],25),res_lsqOlPharr)
                        r2OP = r_squared(DispForceCorr[indxXPercent:indxXXPercent+1,1], fittedUnloadForce)
                        #Compute Slope at slopeCalcPoint (indxXPercent or holdEndCorr)
                        slopeCalcPoint = holdEndCorr
                        SMaxLoad = res_lsqOlPharr.x[0]*res_lsqOlPharr.x[2]*((DispForceCorr[slopeCalcPoint,0]-res_lsqOlPharr.x[1])**(res_lsqOlPharr.x[2]-1))
                        try:        
                            epsilon = (res_lsqOlPharr.x[2])*(1-(res_lsqOlPharr.x[2]-1)*((2*math.gamma((res_lsqOlPharr.x[2])/(2*(res_lsqOlPharr.x[2]-1))))/((math.pi**0.5)*math.gamma(1/(2*(res_lsqOlPharr.x[2]-1))))))                
                        except:
                            epsilon = 0.75
                        hContact = DispForceCorr[slopeCalcPoint,0]-epsilon*(DispForceCorr[slopeCalcPoint,1]/SMaxLoad)
                        radiusContact = (2*hContact*radius-hContact**2)**0.5
                        areaContact = math.pi*(radiusContact**2)
                        EeffOP = (1e6)*(0.5*(math.pi)**0.5)*SMaxLoad*(1/(areaContact**0.5))
                        indentModulusOP = 1/((1/EeffOP)-((1-poissonTip**2)/moduliTip))
                        sampleModulusOP = indentModulusOP*(1-poissonSample**2) 
                        if lowTol*sampleModulusH <= sampleModulusOP <= higTol*sampleModulusH:
                            OPflag=1
                        else:
                            OPexplb=OPexplb+0.05
                            OPexpInit=0.5*(OPexplb+2)
                            if OPexplb>=1.99:
                                lowTol=lowTol-0.025
                                higTol=higTol+0.025
                                OPexplb=1.25
                    OPFit = np.column_stack((DispForceCorr[indxXPercent:indxXXPercent+1,0],fittedUnloadForce))
            
                    # Compute Metrics from corrected curves
                    AreaACorr = [integrator(DispForceCorr[0:loadEndCorr+1,:])]
                    AreaRCorr = [abs(integrator(np.column_stack((np.linspace(1.01*res_lsqOlPharr.x[1],DispForceCorr[holdEndCorr,0],25),fittedUnloadForcetoZero))))]
                    RecoveryRatioCorr = [x / y for x, y in zip(AreaRCorr, AreaACorr)]
                    if AreaRCorr[0]>=AreaACorr[0]:
                        HystereticOrPlasticIndexCorr=0
                        HystereticOrPlasticWorkCorr=0
                    else:
                        HystereticOrPlasticIndexCorr = 1-RecoveryRatioCorr[0]
                        HystereticOrPlasticWorkCorr = AreaACorr[0]-AreaRCorr[0]  
            
                    #Plot for each test
                    fdSegPlotAx = fdSegmentPlotters(TimeDispForceArray, loadEnd, holdEnd, unloadEnd, driftRate, driftOrdinate, driftIndexStart,
                                                    r2driftfit, corrDispTherm, DispForceCorr, loadEndCorr, holdEndCorr, unloadEndCorr,
                                                    path2file, k, os.path.basename(path2file).partition('_')[2].partition('_')[0], FontSizeSubplots)
                    Data_package["Figures"][2*k]=fdSegPlotAx 
                    if 'Advanced' in task:
                        fdHertzOPharrPlotterFig, fdHertzOPharrPlotterAx = fdHertzOPharrPlotter(DispForceCorr,loadEndCorr, holdEndCorr, unloadEndCorr, HertzianFit, OPFit,
                                                                    sampleModulusH, sampleModulusOP, r2H, r2OP,res_lsqOlPharr.x[:], res_lsqH.x[0],
                                                                    tipRadCal, tau, AllPopIns, path2file, k, task,
                                                                    os.path.basename(path2file).partition('_')[2].partition('_')[0], FontSizeSinglePlots)
                    else:
                        fdHertzOPharrPlotterFig, fdHertzOPharrPlotterAx = fdHertzOPharrPlotter(DispForceCorr,loadEndCorr, holdEndCorr, unloadEndCorr, HertzianFit, OPFit,
                                                                    sampleModulusH, sampleModulusOP, r2H, r2OP,res_lsqOlPharr.x[:], res_lsqH.x[0],
                                                                    tipRadCal, np.empty((0,)), np.empty((0,)), path2file, k, task,
                                                                    os.path.basename(path2file).partition('_')[2].partition('_')[0], FontSizeSinglePlots)            
                    Data_package["Figures"][2*k+1]=fdHertzOPharrPlotterAx 
                    if 'Advanced' in task:
                        user_input = ask_user2repeat(fdHertzOPharrPlotterFig)
                    else:
                        plt.close(fdHertzOPharrPlotterFig)
                        user_input = False
                    if user_input == True and 'Advanced' in task:
                        print("Repeating iteration...")
                        sequence.insert(sequence.index(k)+1, k)
                        repeatFlag=True
                    elif user_input == False:
                        repeatFlag=False
                        if 'Advanced' in task:
                            print("Continuing to the next iteration...")                
                        ExpResults[k,0,0] = k
                        ExpResults[k,0:TimeDispForceArray.shape[0],1:4] = TimeDispForceArray
                        ExpResults[k,0,4:8] = np.column_stack((loadEnd, holdEnd, unloadEnd, driftRate))
                        ExpResults[k,0:AllPopInsUC.shape[0],8:10] = AllPopInsUC
                        ExpResults[k,0,10] = np.sum(np.isfinite(AllPopIns[:,0]))
                        ExpResults[k,0:2,11] = np.vstack((DispForceCorrThMC[best_ZPindx,0],DispForceCorrThMC[best_ZPindx,1])).reshape(2)
                        ExpResults[k,0:DispForceCorr.shape[0],12:14] = DispForceCorr
                        ExpResults[k,0,14:17] = np.column_stack((loadEndCorr, holdEndCorr, unloadEndCorr))
                        if 'Advanced' in task:             
                            ExpResults[k,0:AllPopIns.shape[0],17:19] = AllPopIns            
                        ExpResults[k,0,19] = AreaACorr[0]
                        ExpResults[k,0,20] = AreaRCorr[0]
                        ExpResults[k,0,21] = HystereticOrPlasticWorkCorr   
                        ExpResults[k,0,22] = HystereticOrPlasticIndexCorr            
                        ExpResults[k,0:3,23] = np.vstack((indentModulusH, sampleModulusH, r2H)).reshape(3) 
                        ExpResults[k,0:7,24] = np.vstack((indentModulusOP, sampleModulusOP, res_lsqOlPharr.x[0],
                                                        res_lsqOlPharr.x[1],res_lsqOlPharr.x[2], r2OP, hContact)).reshape(7)
                        if 'Advanced' in task:     
                            ExpResults[k,0,25] = tau 
                            ExpResults[k,0,26] = tau/(AllPopIns[0,1]/loadRate)
                            ExpResults[k,0,27] = CumExcursionLength              
                        Data_package["Dataframes"][k+1] = Array2DataframeSingleStep(ExpResults[k,:,:],instrumentUsed4Indentation)
                        #Save the list of dataframes to pickle
                        savedf2pickle(Data_package, path2saveDataPackage, task, os.path.basename(path2file).partition('_')[2].partition('_')[0])
                except Exception as e:
                    exc_type, exc_obj, exc_tb = sys.exc_info()
                    print(f"Skipping single-step indentation test {k} due to error: {e}, at line {exc_tb.tb_lineno}. Please check it after done")
                    continue
            plt.close('all')
        elif 'AFM' in task.replace(" ", ""):
            instrumentUsed4Indentation = 'AFM'
            path2file = getDataFile4Analysis(instrumentUsed4Indentation)
            AFMClass, nominalTipRadius_nm, TipAR, Deflect_Sensitivity_nmV, Cantilever_Stiffness_Nm, LoadRate_nmsec, Temperature_K = AFMInstrumentSelector()
            filetype, text_filesA, text_filesR, text_filesAR, nfiles = determineFileType(path2file, AFMClass)  
            _, _, ARCurvesPerFile, _ , _= getHeaderandUnitsScaleFactor(os.path.dirname(path2file),text_filesAR[0],filetype, AFMClass)
            #Get elastic limit from user
            knownElasticLimit=elasticLimitSelector(1, [os.path.basename(path2file)], instrumentUsed4Indentation, task.replace(" ", ""))
            #Look up Poisson's Ratio or ask user to input
            tipMaterial = os.path.basename(path2file).partition('_')[0].partition('-')[2]
            sampleMaterial = os.path.basename(path2file).partition('_')[2].partition('_')[0].partition('-')[2]
            ETentative_Sample = retrieveRefProperties(sampleMaterial)[0]
            nuTentative_Sample = retrieveRefProperties(sampleMaterial)[1]
            EEstimated_Sample, poissonSample = SamplePropertiesPrompt(ETentative_Sample,nuTentative_Sample)
            #Create ExpResults Matrix to store Results
            ExpResults = np.full((ARCurvesPerFile*nfiles, nRowsPreAlloc, 30), np.nan)
            df_Parameters = pd.DataFrame({'RawDataFile': [text_filesAR[0]],
                                        'AFM': [AFMClass],
                                        'ExperimentType': ['SingleStep'],
                                        'Sample': [os.path.basename(path2file).partition('_')[2].partition('_')[0]],
                                        'Tip': [os.path.basename(path2file).partition('_')[0]],
                                        'DeflectionSensitivity(nm/V)': [Deflect_Sensitivity_nmV],
                                        'CantileverStiffness(N/m)': [Cantilever_Stiffness_Nm],
                                        'Tip Radius Nominal(nm)':[nominalTipRadius_nm],
                                        'TipAspectRatio': [TipAR], 
                                        'Modulus Tip(GPa)':[retrieveRefProperties(tipMaterial)[0]],
                                        'Poisson Tip':[retrieveRefProperties(tipMaterial)[1]],
                                        'Temperature(K)':[Temperature_K],
                                        'LoadRate(nN/s)': [LoadRate_nmsec]})
            nTests = int(ARCurvesPerFile*nfiles)
            if TipAR==1.0:
                indenterGeom='Sphere'
            else:
                indenterGeom='Ellipsoid'
            pickle_files = [file for file in os.listdir(os.path.dirname(path2file)) if file.endswith('.pkl')]
            if len(pickle_files)==0:
                Data_package = {'Readme': """This pickle file contains dataframes and figures with information from AFM-indentation tests.""",
                'Dataframes': [],
                'Figures':[None]*(2*nTests)
                    }         
                Data_package["Dataframes"]=[pd.DataFrame() for _ in range(nTests+1)]
                Data_package["Dataframes"][0]=df_Parameters        
            else:
                with open(os.path.dirname(path2file) + '/ExpResults_'+os.path.basename(path2file).partition('_')[2].partition('_')[0]+'.pkl', 'rb') as pickle_files:
                    Data_package = pickle.load(pickle_files)
                    Data_package["Dataframes"][0]=df_Parameters
            repeatFlag=False
            sequence=list(range(0,10))
            for k in sequence:
                try: 
                    plt.close('all')
                    print('Working on single-step indentation test ' + str(k)+' of '+str(nTests-1)) 
                    if filetype==0:
                        scDispA, scVoltageA, _, _ = getHeaderandUnitsScaleFactor(os.path.dirname(path2file),text_filesA[k],filetype, AFMClass)  
                        scDispR, scVoltageR, _, _ = getHeaderandUnitsScaleFactor(os.path.dirname(path2file),text_filesR[k],filetype, AFMClass)     
                        data_A = pd.read_csv(os.path.dirname(path2file) + '/' + text_filesA[k], sep='\t', usecols=[0, 1])
                        data_R = pd.read_csv(os.path.dirname(path2file) + '/' + text_filesR[k], sep='\t', usecols=[0, 1])
                    elif filetype==1:
                        scDispA, scVoltageA, _, orderData, physunitsType = getHeaderandUnitsScaleFactor(os.path.dirname(path2file),text_filesAR[0],filetype, AFMClass)
                        data_A = pd.read_csv(os.path.dirname(path2file) + '/' + text_filesAR[0], sep='\t', usecols=[4*k+orderData[0], 4*k+orderData[1]]).iloc[:, ::-1]
                        data_R = pd.read_csv(os.path.dirname(path2file) + '/' + text_filesAR[0], sep='\t', usecols=[4*k+orderData[2], 4*k+orderData[3]]).iloc[:, ::-1]
                        scDispR = scDispA
                        scVoltageR = scVoltageA
                    data_A.dropna(inplace=True)
                    data_R.dropna(inplace=True)  
                    #Padding in case dimensions are different
                    col1=scDispA*(data_A.iloc[:,0].to_numpy())
                    col2=scVoltageA*(data_A.iloc[:,1].to_numpy())
                    col3=scDispR*(data_R.iloc[:data_A.shape[0],0].to_numpy())
                    col4=scVoltageR*(data_R.iloc[:data_A.shape[0],1].to_numpy())        
                    if len(col3)>len(col1):
                        col3=col3[:len(col1)]
                        col4=col4[:len(col1)]
                    elif len(col1)>len(col3):
                        col3 = np.pad(col3, (0, len(col1) - len(col3)), constant_values=col3[-1])
                        col4 = np.pad(col4, (0, len(col1) - len(col4)), constant_values=col4[-1])
                    #Assemble an Approach Retract Matrix
                    ARData = np.column_stack((col1,col2,col3,col4))
                    #Find Snap-In and Snap-Out Instability Locations
                    Snaps = SnapInSnapOutLocator(ARData, df_Parameters['ExperimentType'].iloc[0])
                    ARData_Detrended, nPointsBeforeAfterMin = polynomialDetrend(ARData, Snaps, df_Parameters['ExperimentType'].iloc[0])
                    # Look for Preliminary Zero-Point
                    ZPIndex, piecewiseFitXY = ZeroPointLocator(ARData_Detrended, Snaps)

                    #Plotter 1
                    detrendZPPlotterAx = DetrenderZeroPointPlotter(ARData, ARData_Detrended, Snaps, nPointsBeforeAfterMin, ZPIndex, piecewiseFitXY, AFMClass+'_'+physunitsType, 
                                                                os.path.basename(path2file).partition('_')[2].partition('_')[0], FontSizeSubplots, os.path.dirname(path2file), k)
                    Data_package["Figures"][2*k]=detrendZPPlotterAx

                    # Build Approach-Retract Curves   
                    ACurve = ARData_Detrended[Snaps[0]+ZPIndex:,0:2]-[ARData_Detrended[Snaps[0]+ZPIndex,0],ARData_Detrended[Snaps[0]+ZPIndex,1]]        
                    RCurveTemp = ARData_Detrended[0:Snaps[1],2:4]-([ARData_Detrended[Snaps[0]+ZPIndex,0],ARData_Detrended[Snaps[0]+ZPIndex,1]])        
                    RCurve = RCurveTemp-[RCurveTemp[0,0]-ACurve[-1,0],abs(RCurveTemp[0,1])-ACurve[-1,1]]     
                    ARCurves = np.vstack((ACurve,RCurve))   
                    ARSeparatorIndex=len(ACurve)

                    #Convert ARCurves to Displacement-Force
                    FDCurves = np.empty(ARCurves.shape)
                    S = Deflect_Sensitivity_nmV
                    FDCurves [:,0] = ARCurves [:,0]-ARCurves [:,1]*S
                    FDCurves [:,1] = ARCurves [:,1]*Cantilever_Stiffness_Nm*S
                    FDCurveA = FDCurves[:ARSeparatorIndex,:]
                    FDCurveR = FDCurves[ARSeparatorIndex:,:]
                    DisForceUncorr = np.vstack((FDCurveA,FDCurveR))

                    loadEnd = ARSeparatorIndex-1
                    unloadEnd = FDCurves.shape[0]

                    #Detect PopIns in the Force Displacement Approach Curve
                    if ~np.isnan(knownElasticLimit[0]):
                        if ~np.isinf(knownElasticLimit[0]):
                            indxelasticLimit = np.argmin(abs(FDCurveA[:,1]-knownElasticLimit[0]))
                            AllPopInsUC = FDCurveA[indxelasticLimit,:].reshape(1, -1)
                        else:
                            AllPopInsUC=[]
                    else:
                        if repeatFlag==False:
                            FDPopIns = PopInDetection(FDCurveA)
                        else:
                            FDPopIns = AllPopInsUC
                        #Binary Indicator for PopIn detection in the Force Displacement Approach Curve       
                        if FDPopIns.shape[0]!=0:
                            popInDetectionFlagFD=1
                        else:
                            popInDetectionFlagFD=0    
                        AllPopInsUC, skipExpStatus = PopInSelectionPlotter(popInDetectionFlagFD, FDCurveA, FDPopIns, FDCurves, instrumentUsed4Indentation, FontSizeSinglePlots)   
                        if skipExpStatus:
                            continue
                    #Binary Indicator for Overall PopIn detection in the Approach Curves
                    if len(AllPopInsUC)!=0:
                        popInDetectionFlag=1
                    else:
                        popInDetectionFlag=0 
                        AllPopInsUC=np.column_stack((np.inf,np.inf))
                    idx=[]            
                    #Determine Range for Hertzian Fit 
                    if popInDetectionFlag==1:
                        for z in range(0,AllPopInsUC.shape[0]):
                            idx.append(np.abs(FDCurveA[:,0] - AllPopInsUC[z,0]).argmin())
                        x4fit = FDCurveA[:idx[0]+1,0]
                        y4fit = FDCurveA[:idx[0]+1,1]                    
                    else:
                        idx.append(np.abs(FDCurveA[:,1] - 0.9*FDCurveA[loadEnd,1]).argmin())
                        x4fit = FDCurveA[:idx[0]+1,0]
                        y4fit = FDCurveA[:idx[0]+1,1]
                        
                    #Retrieve the material properties of the tip    
                    moduliTip = df_Parameters['Modulus Tip(GPa)'].iloc[0]
                    poissonTip = df_Parameters['Poisson Tip'].iloc[0]

                    #Fitting of the Unloading Curve via Oliver-Pharr
                    r2OP=0.1;stp=0.05;deltaStp=0.01;fractionfromMaxLoad2startFit=0.40;fractionfromMaxLoad2endFit=0.10
                    smoothfrac=0.05;deltaSmoothfrac=0.1;rThreshold=0.95; numiter=0; maxIter=10000
                    while r2OP<=rThreshold and numiter<=maxIter:
                        numiter+=1
                        idxStartUL = np.abs(FDCurveR[:,1] - (1-stp)*max(FDCurveR[:,1])).argmin()
                        if fractionfromMaxLoad2endFit*max(FDCurveR[:,1])>0.:
                            idxEndUL=np.abs(FDCurveR[:,1] - fractionfromMaxLoad2endFit*max(FDCurveR[:,1])).argmin()
                        else:
                            idxEndUL = np.abs(FDCurveR[:,1] - 0.).argmin()
                        x4fitU = FDCurveR [idxStartUL:idxEndUL+1,0]
                        y4fitU =  FDCurveR [idxStartUL:idxEndUL+1,1] 
                        smoothXU = sm.nonparametric.lowess(x4fitU, y4fitU, frac=smoothfrac)
                        x4fitU=np.flipud(smoothXU[:,1]) 
                        try:
                            res_lsqOlPharr = least_squares(OliverPharrUnloadingFunction, np.array([1000,0.5*x4fitU[-1],1.35]),  
                                                        args=(x4fitU, y4fitU),
                                                        bounds=([0,0,1.2], [np.inf,2*np.min(x4fitU),1.7]))
                        except:
                            if stp+deltaStp<=fractionfromMaxLoad2startFit:
                                stp+=deltaStp
                            continue
                        fittedForceU = gen_ForceOlPharr(x4fitU,res_lsqOlPharr)
                        OPFit = np.column_stack((x4fitU,fittedForceU))
                        r2OP = r_squared(y4fitU, fittedForceU)
                        SMaxLoad = res_lsqOlPharr.x[0]*res_lsqOlPharr.x[2]*((x4fitU[0]-res_lsqOlPharr.x[1])**(res_lsqOlPharr.x[2]-1))
                        try:
                            epsilon = (res_lsqOlPharr.x[2])*(1-(res_lsqOlPharr.x[2]-1)*((2*math.gamma((res_lsqOlPharr.x[2])/(2*(res_lsqOlPharr.x[2]-1))))/((math.pi**0.5)*math.gamma(1/(2*(res_lsqOlPharr.x[2]-1))))))
                        except:
                            epsilon=0.75
                        hContact = x4fitU[0]-epsilon*(fittedForceU[0]/SMaxLoad)
                        hElas = x4fitU[0]-res_lsqOlPharr.x[1]
                        if indenterGeom=='Sphere':
                            E_mean=EEstimated_Sample;E_std=0.1*EEstimated_Sample
                            E_lb=E_mean-1*E_std
                            E_ub=E_mean+1*E_std
                            R_Tip_nm_lb = (SMaxLoad**2)/(8*(E_ub**2)*hContact)+hContact/2
                            R_Tip_nm_ub = (SMaxLoad**2)/(8*(E_lb**2)*hContact)+hContact/2
                            R_Tip_nm = (SMaxLoad**2)/(8*(E_mean**2)*hContact)+hContact/2
                            ContRadius = (2*hContact*R_Tip_nm-hContact**2)**0.5  
                            ContRadius_lb = (2*hContact*R_Tip_nm_lb-hContact**2)**0.5  
                            ContRadius_ub = (2*hContact*R_Tip_nm_ub-hContact**2)**0.5
                            EeffOP = SMaxLoad/(2*ContRadius)
                            EeffOP_lb = SMaxLoad/(2*ContRadius_ub)
                            EeffOP_ub = SMaxLoad/(2*ContRadius_lb)   
                            indentModulusOP = 1/((1/EeffOP)-(1/(moduliTip/(1-poissonTip**2))))
                            sampleModulusOP = indentModulusOP*(1-poissonSample**2)
                            tipRadiusOP = R_Tip_nm        
                        if 0.99*rThreshold<r2OP<rThreshold and smoothfrac+deltaSmoothfrac<=0.75:
                            smoothfrac+=deltaSmoothfrac
                        else:
                            if stp+deltaStp<=fractionfromMaxLoad2startFit:
                                stp+=deltaStp
                            else:
                                rThreshold-=0.01
                                stp=0
                                smoothfrac=0.05              
                    
                    #Fitting of the Loading Curve
                    approach='Pathak-Kalidindi'
                    if approach=='Pathak-Kalidindi':
                        min_cost = np.inf                             
                        # Iterate over each possible (x0, B) pair from the data
                        for i in range(idx[0]):
                            #Use every point in the curve as candidate for ZP
                            h0_candidate = x4fit[i]
                            p0_candidate = y4fit[i]                        
                            # Perform the least-squares optimization
                            res_lsqHertzL = least_squares(HertzianForceDepthFunctionUnknownEeffRXYOffset, 
                                                    np.array([EeffOP,tipRadiusOP]), args=(x4fit, y4fit,h0_candidate, p0_candidate),
                                                    bounds=([EeffOP_lb, R_Tip_nm_lb],[EeffOP_ub, R_Tip_nm_ub]))
                            # Check if this fit is better than previous ones
                            if res_lsqHertzL.cost < min_cost:
                                min_cost = res_lsqHertzL.cost
                                best_ZPindx=i
                                mask = x4fit[best_ZPindx:] - x4fit[best_ZPindx] >= 0
                                x4fitL = (x4fit[best_ZPindx:] - x4fit[best_ZPindx])[mask]
                                y4fitL=(y4fit[best_ZPindx:] - y4fit[best_ZPindx])[mask]
                                fittedForce = gen_ForceHertz1(x4fitL,res_lsqHertzL.x[0],res_lsqHertzL.x[1])
                                HertzianFit = np.column_stack((x4fitL,fittedForce))
                                r2H = r_squared(y4fitL, fittedForce)
                                indentModulusH = 1/((1/res_lsqHertzL.x[0])-(1/(moduliTip/(1-poissonTip**2))))
                                sampleModulusH = indentModulusH*(1-poissonSample**2)
                                effectiveModulusH = res_lsqHertzL.x[0]
                                tipRadiusH = res_lsqHertzL.x[1]

                    #Re-Define Indentation Curves with ZP from best Hertzian Analysis
                    FDCurvesCorrA = np.full((len(FDCurveA[int(best_ZPindx):,0]),2), np.nan)            
                    FDPopInsCorr = np.full((1,2*AllPopInsUC.shape[0]), np.nan)   
                    FDCurvesCorrA[:len(FDCurveA[int(best_ZPindx):,0]),0] = FDCurveA[int(best_ZPindx):,0]-FDCurveA[int(best_ZPindx),0]   
                    FDCurvesCorrA[:len(FDCurveA[int(best_ZPindx):,0]),1] = FDCurveA[int(best_ZPindx):,1]-FDCurveA[int(best_ZPindx),1] 
                    FDCurvesCorrR = np.column_stack((FDCurveR[:,0]-(FDCurveR[0,0]-FDCurvesCorrA[-1,0]),FDCurveR[:,1]-(FDCurveR[0,1]-FDCurvesCorrA[-1,1])))
                    DispForceCorr = np.vstack((FDCurvesCorrA, FDCurvesCorrR))
                    loadEndCorr = FDCurvesCorrA.shape[0]-1; unloadEndCorr = DispForceCorr.shape[0]-1
                    FDPopInsCorr = np.column_stack((AllPopInsUC[:,0]-FDCurveA[int(best_ZPindx),0],AllPopInsUC[:,1]-FDCurveA[int(best_ZPindx),1]))
                    if popInDetectionFlag!=0:
                        ContRadiusCorr = ((3/4)*(FDPopInsCorr[0,1]*(tipRadiusH*(1/effectiveModulusH))))**(1/3) 
                        tauCorr = 0.31*(3/(2*math.pi*(ContRadiusCorr**2)))*FDPopInsCorr[0,1]
                        taurateCorr = tauCorr/((FDPopInsCorr[0,0])/LoadRate_nmsec)
                        CumExcursionLengthCorr = abs(np.max(((3/4)*np.linspace(0,np.max(FDCurvesCorrA[:,1]),50)*((1/tipRadiusH)**(1/2))*(1/effectiveModulusH))**(2/3))-np.max(FDCurvesCorrA[:,0]))
                    # Compute Metrics from corrected curves
                    AreaACorr = [integrator(FDCurvesCorrA)]
                    AreaRCorr = [abs(integrator(FDCurvesCorrR))]
                    RecoveryRatioCorr = [x / y for x, y in zip(AreaRCorr, AreaACorr)]
                    if AreaRCorr[0]>=AreaACorr[0]:
                        HystereticOrPlasticIndexCorr=0
                        HystereticOrPlasticWorkCorr=0
                    else:
                        HystereticOrPlasticIndexCorr = 1-RecoveryRatioCorr[0]
                        HystereticOrPlasticWorkCorr = AreaACorr[0]-AreaRCorr[0]  

                    #Plot for each test
                    if 'Advanced' in task:
                        fdHertzOPharrPlotterFig, fdHertzOPharrPlotterAx = fdAFMHertzOPharrPlotter(DisForceUncorr, idxStartUL+ARSeparatorIndex, idxEndUL+ARSeparatorIndex, best_ZPindx, idx[0], popInDetectionFlag, AllPopInsUC,
                                                                        DispForceCorr, loadEndCorr, unloadEndCorr, HertzianFit, OPFit,
                                                                        sampleModulusH, sampleModulusOP, r2H, r2OP, res_lsqOlPharr.x[:], effectiveModulusH,
                                                                        tipRadiusOP, tipRadiusH, tauCorr, FDPopInsCorr, os.path.dirname(path2file), k, task,
                                                                        os.path.basename(path2file).partition('_')[2].partition('_')[0], FontSizeSinglePlots)
                    else:
                        fdHertzOPharrPlotterFig, fdHertzOPharrPlotterAx = fdAFMHertzOPharrPlotter(DisForceUncorr, idxStartUL+ARSeparatorIndex, idxEndUL+ARSeparatorIndex, best_ZPindx, idx[0], popInDetectionFlag, AllPopInsUC,
                                                                        DispForceCorr, loadEndCorr, unloadEndCorr, HertzianFit, OPFit,
                                                                        sampleModulusH, sampleModulusOP, r2H, r2OP, res_lsqOlPharr.x[:], effectiveModulusH,
                                                                        tipRadiusOP, tipRadiusH, np.empty((0,)), np.empty((0,)), os.path.dirname(path2file), k, task,
                                                                        os.path.basename(path2file).partition('_')[2].partition('_')[0], FontSizeSinglePlots)            
                    Data_package["Figures"][2*k+1]=fdHertzOPharrPlotterAx 
                    if 'Advanced' in task:
                        user_input = ask_user2repeat(fdHertzOPharrPlotterFig)
                    else:
                        plt.close(fdHertzOPharrPlotterFig)
                        user_input = False
                    if user_input == True and 'Advanced' in task:
                        print("Repeating iteration...")
                        sequence.insert(sequence.index(k)+1, k)
                        repeatFlag=True
                    elif user_input == False:
                        repeatFlag=False
                        if 'Advanced' in task:
                            print("Continuing to the next iteration...")                
                        ExpResults[k,0,0] = k
                        ExpResults[k,0:ACurve.shape[0],1:3] = ACurve
                        ExpResults[k,0:RCurve.shape[0],3:5] = RCurve
                        ExpResults[k,0:FDCurveA.shape[0],5:7] = FDCurveA
                        ExpResults[k,0:FDCurveR.shape[0],7:9] = FDCurveR
                        ExpResults[k,0,9:11] = np.column_stack((loadEnd, unloadEnd))
                        ExpResults[k,0:AllPopInsUC.shape[0],11:13] = AllPopInsUC
                        ExpResults[k,0,13] = np.sum(np.isfinite(AllPopInsUC[:,0]))
                        ExpResults[k,0:2,14] = np.vstack((FDCurveA[best_ZPindx,0],FDCurveA[best_ZPindx,1])).reshape(2)
                        ExpResults[k,0:DispForceCorr.shape[0],15:17] = DispForceCorr
                        ExpResults[k,0,17:19] = np.column_stack((loadEndCorr, unloadEndCorr))
                        if 'Advanced' in task:             
                            ExpResults[k,0:FDPopInsCorr.shape[0],19:21] = FDPopInsCorr            
                        ExpResults[k,0,21] = AreaACorr[0]
                        ExpResults[k,0,22] = AreaRCorr[0]
                        ExpResults[k,0,23] = HystereticOrPlasticWorkCorr   
                        ExpResults[k,0,24] = HystereticOrPlasticIndexCorr   
                        ExpResults[k,0:4,25] = np.vstack((indentModulusH, sampleModulusH, tipRadiusH, r2H)).reshape(4) 
                        ExpResults[k,0:8,26] = np.vstack((indentModulusOP, sampleModulusOP, res_lsqOlPharr.x[0],
                                                        res_lsqOlPharr.x[1], res_lsqOlPharr.x[2], r2OP, tipRadiusOP,
                                                        hContact)).reshape(8)
                        if 'Advanced' in task:     
                            ExpResults[k,0,27] = tauCorr 
                            ExpResults[k,0,28] = taurateCorr
                            ExpResults[k,0,29] = CumExcursionLengthCorr              
                        Data_package["Dataframes"][k+1] = Array2DataframeSingleStep(ExpResults[k,:,:],instrumentUsed4Indentation)
                        #Save the list of dataframes to pickle
                        savedf2pickle(Data_package, os.path.dirname(path2file), task, os.path.basename(path2file).partition('_')[2].partition('_')[0])
                except Exception as e:
                    exc_type, exc_obj, exc_tb = sys.exc_info()
                    print(f"Skipping single-step indentation test {k} due to error: {e}, at line {exc_tb.tb_lineno}. Please check it after done")
                    continue
        plt.close('all')        
