            forceUnits = data[0].columns[retrieveForceDispIndices+1][data[0].columns[retrieveForceDispIndices+1].find('(') + 1:data[0].columns[retrieveForceDispIndices+1].find(')')]
            retrieveLoadEndIndices = [i for i, col in enumerate(data[0].columns) if 'Index End Load Segment' in col and i > retrieveForceDispIndices]
            retrieveUnloadEndIndices = [i for i, col in enumerate(data[0].columns) if 'Index End Unload Segment' in col and i > retrieveForceDispIndices]
            fdCurvesA = np.full((len(data),nRowsPreAlloc,2),np.nan)
            fdCurvesR = np.full((len(data),nRowsPreAlloc,2),np.nan)
            maxForceA = []
            maxForceR = []; minForceR = []        
            for k in range(0,len(data)):
                fdCurvesA[k,0:int(ExpResults[k,0,retrieveLoadEndIndices]+1),:] = ExpResults[k,0:int(ExpResults[k,0,retrieveLoadEndIndices]+1),retrieveForceDispIndices:retrieveForceDispIndices+2] 
                fdCurvesR[k,0:len(ExpResults[k,int(ExpResults[k,0,retrieveLoadEndIndices]):int(ExpResults[k,0,retrieveUnloadEndIndices]+1),retrieveForceDispIndices:retrieveForceDispIndices+2]),:] = ExpResults[k,
                                                                                                                         int(ExpResults[k,0,retrieveLoadEndIndices]):int(ExpResults[k,0,retrieveUnloadEndIndices]+1),
                                                                                                                         retrieveForceDispIndices:retrieveForceDispIndices+2] 
                maxForceA.append(np.max(remove_nans(ExpResults[k,0:int(ExpResults[k,0,retrieveLoadEndIndices]+1),retrieveForceDispIndices+1], 0))) 
