                interpolated_fdForceA[j,:,:] = np.column_stack((fForceA(common_fA),common_fA))
                fForceR = interp1d(remove_nans(fdCurvesR[j,:,1],0),remove_nans(fdCurvesR[j,:,0],0), kind='linear', bounds_error=False)
                interpolated_fdForceR[j,:,:] = np.column_stack((fForceR(common_fR),common_fR))
