            AnalyzedData_package["Dataframes"].append(pd.DataFrame(np.column_stack((AvgPhData,analyzedData[:,:])),
                                                                   columns=['AvgDisp('+displacementUnits+')',
                                                                            'AvgForce('+forceUnits+')',
                                                                            'DispStdDev('+displacementUnits+')'] + variablesplotterHeaders))            
