# Main window setup
root = tk.Tk()
root.title("SpherIndent")
center_window(root, 750, 450)
root.configure(bg="white")
root.protocol("WM_DELETE_WINDOW", lambda: on_closing(root))
try:
    bg_image = Image.open(os.path.dirname(os.path.realpath(__file__))+'\\Background.jpg')
    bg_photo = ImageTk.PhotoImage(bg_image)
    bg_label = tk.Label(root, image=bg_photo)
    bg_label.image = bg_photo
    bg_label.place(x=0, y=0, relwidth=1, relheight=1)
    frame = tk.Frame(root, bg="white")
    frame.pack(pady=90)
except:
    tk.Label(root, text="SpherIndent", bg="white", font=("Arial", 20, "bold")).pack(pady=5)
    frame = tk.Frame(root, bg="white")
    frame.pack(pady=20)
# Dropdown Menu Options
options = [
    ("Postprocess Experiments", ["", 
                                 "Single-Step Nano-Indentation_Basic",
                                 "Single-Step AFM-Indentation_Basic",
                                 "Single-Step Nano-Indentation_Advanced",
                                 "Single-Step AFM-Indentation_Advanced",
                                 "Multi-Step Nano-Indentation_Stress-Strain Curve",
                                 "Multi-Step AFM-Indentation_Stress-Strain Curve"]),
    ("Calibrate Spherical Tip/Machine Compliance (IIT Only)", ["", 
                                                    "Direct Input",
                                                    "N≥2 Reference Materials [Chudoba Method (2000)]",
                                                    "N≥2 Reference Materials [Li (2013)|Avadanii (2025) Methods]",
                                                    "Calibration Aggregator"]),
    ("Analyze Indenter Tip Image", ["", 
                                    "Choose Image File"]),
    ("Analyze Results", ["", 
                         "Basic [Avg. P-h Curve | Modulus (Hertz,O-P) | Metrics]", 
                         "Advanced [Basic+Incipient Plasticity Metrics or ISS]",
                         "Simple FD Curve Averager (copy-paste)",
                         "Simple Residual Surfaces Averager (copy-paste)",
                         "Damage Detector (Beta)"]),
    ("Retrieve & Inspect Pickle File", ["", 
                                        "Choose Pickle File"]),
]
dropdowns = []
for label_text, values in options:
    row = tk.Frame(frame, bg="white")
    row.pack(pady=(20,0), fill="x")
    tk.Label(row, text=label_text, width=41, font=("Arial", 12, "bold"), anchor="w", bg="white").pack(side="left", padx=5)
    var = tk.StringVar()
    dropdown = ttk.Combobox(row, textvariable=var, values=values, state="readonly", width=50)
    dropdown.pack(side="left", padx=0)
    # Bind with identifier
    dropdown.bind("<<ComboboxSelected>>", lambda e, dd=dropdown, lbl=label_text: on_select(e, lbl, dd))
    dropdowns.append((label_text, dropdown))
#Proceed and About Buttons
proceed_btn = tk.Button(root, text="Next", font=("Arial", 12, "bold"), command=proceedButton).place(relx=0.5, rely=0.8, anchor="center")
about_btn = tk.Button(root, text="About", font=("Arial", 12, "bold"),  command=displayAboutInfo).place(relx=0.5, rely=0.935, anchor="center")
#Main Loop
root.mainloop()



